quests[4784] = { id = 4784, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Komponenten für die verzauberte Goldblutrobe", description = "Ich brauche jetzt nur noch drei Dinge, {name}, dann kann ich Eure Robe fertig stellen.\n\nZuerst brauche ich das feine Goldgarn, das Xizk für Euch gesponnen hat. Kehrt zu ihm nach Beutebucht zurück und holt es.\n\nAls Zweites brauche ich ein paar glimmende Kohlen von den Feuerelementaren im Arathihochland. Wenn ich mich recht erinnere, leben sie im Westen in der Nähe des Thoradinswalls.\n\nAls Letztes benötige ich dann noch einen von Euch geschaffenen Seelensplitter.\n\nKommt hierher zum Turm zurück, sobald Ihr alle Komponenten habt, dann stelle ich Eure Robe fertig.", sourceObjective = "Bringt Menara Leerbringer im Brachland Goldgarn, 2 glimmende Kohlen und einen Seelensplitter.", sourceObjectiveStatus = "unverified-source-field" }
quests[4785] = { id = 4785, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feiner Goldfaden" }
quests[4786] = { id = 4786, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die fertiggestellte Robe", description = "Jetzt schneidere ich die Robe für Euch. Es dauert nur einen Augenblick. Geht nicht zu weit fort, ja?", sourceObjective = "Wartet, bis Menara Leerbringer Eure Robe fertiggestellt hat, und sprecht dann noch einmal mit ihr.", sourceObjectiveStatus = "unverified-source-field" }
quests[4787] = { id = 4787, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das uralte Ei", description = "Mosh'arus Prophezeiung spricht von einem uralten Ei. Es ist ein Relikt aus einer Zeit, als die Trolle noch über riesige Reiche herrschten, und es hat die Kraft, die Essenz von Hakkar zu binden. Möglicherweise ist es das einzige Mittel, um unsere Welt vor diesem Bösen zu schützen.\n\nBringt mir das uralte Ei, {name}. Man sagt, dass es tief verborgen in Jintha'Alor im Hinterland liegt, in einer Höhle hinter dem Amphitheater am obersten Punkt der Stadt.", sourceObjective = "Bringt das uralte Ei zu Yeh'kinya nach Tanaris.", sourceObjectiveStatus = "unverified-source-field" }
quests[4788] = { id = 4788, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die letzten Schrifttafeln", description = "Während ich die dritte und vierte Schrifttafel von Mosh'aru überprüfe, müsst ihr die fünfte und sechste finden! Es wird nicht einfach sein, da sie in den Händen der Trolle des Gluthauerstamms auf der Schwarzfelsspitze sind. Die Spitze ist ein dunkler Berg aus Feuer zwischen der Brennenden Steppe und der Sengenden Schlucht.\n\nViel Glück, {name}. Die Schwarzfelsspitze ist kein Ort für anständige Leute...", sourceObjective = "Bringt Ausgrabungsleiter Eisenschuh in Tanaris die fünfte und sechste Schrifttafel von Mosh'aru.", sourceObjectiveStatus = "unverified-source-field" }
quests[4801] = { id = 4801, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "E'ko der Frostsäbler" }
quests[4802] = { id = 4802, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "E'ko der Winterfelle" }
quests[4803] = { id = 4803, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "E'ko eines Splitterzahns" }
quests[4804] = { id = 4804, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "E'ko der Eiswindschimären" }
quests[4805] = { id = 4805, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "E'ko der Eisdistelyetis" }
quests[4806] = { id = 4806, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "E'ko der Frosthagelriesen" }
quests[4807] = { id = 4807, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "E'ko der Wildekin" }
quests[4808] = { id = 4808, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Felnok Stahlfeder", description = "Ich habe noch eine weitere kleine Bitte an Euch.\n\nMeine anfänglichen Studien bezüglich der Essenz, die Ihr gesammelt habt, haben ergeben, dass es wohl möglich ist, die Eier der Großdrachenwelpen einzufrieren und so zu konservieren! Ich möchte diese Theorie überprüfen, aber zuerst benötige ich speziell angefertigte Komponenten der Ingenieurskunst. Mein Kollege Felnok Stahlfeder kann sie herstellen.\n\nHier, bringt Felnok diesen Brief. Darin steht, was ich benötige. Ihr findet Felnok in Winterquell in der Ewigen Warte.", sourceObjective = "Gebt Felnok Stahlfeder in der Ewigen Warte in Winterquell Tinkees Brief.", sourceObjectiveStatus = "unverified-source-field" }
quests[4809] = { id = 4809, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hörner der Eiswindschimären", description = "Ich habe fast alles, was Tinkee benötigt, aber mir fehlt eine wichtige Komponente, und das sind Eiswindschimärenhörner. Die Hörner der Eiswindschimären von Winterquell sind eine konzentrierte Kältequelle, aber man kann nur makellose, unbeschädigte Hörner verwenden! Ich brauche ein paar davon, um Tinkees Auftrag zu erfüllen.\n\nBringt mir unbeschädigte Hörner der Eiswindschimären, dann schnüre ich ein Päckchen für Tinkee zusammen.", sourceObjective = "Beschafft Euch 8 unbeschädigte Hörner.", sourceObjectiveStatus = "unverified-source-field" }
quests[4810] = { id = 4810, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zu Tinkee", description = "Gut, alles ist bereit und verpackt und transportfertig! Viel Glück auf Eurer Reise und richtet Tinkee aus, dass sie mir was schuldet!", sourceObjective = "Bringt Tinkee Kesseldampf auf dem Flammenkamm in der Brennenden Steppe Felnoks Päckchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[4811] = { id = 4811, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der rote Kristall", description = "Im Osten streifen immer mehr feindliche Mondkin umher. Man dachte einst, dass sie sanftmütige, fast mystische Kreaturen wären. Wenn auch viele ihnen weiterhin Ehrfurcht entgegenbringen, zwingt mich die Sicherheit Auberdines, die Sache realistischer zu sehen.\n\nIch habe Berichte erhalten, dass es die Mondkin zu einem großen roten Kristall an der östlichen Bergkette von Dunkelküste zieht. Niemand weiß, was dieser Kristall ist oder ob er wirklich existiert. Ich möchte, dass Ihr ihn dort sucht und mir meldet, was Ihr vorgefunden habt.", sourceObjective = "Reist von Auberdine nach Osten und sucht nach einem großen, roten Kristall entlang der östlichen Bergkette von Dunkelküste. Informiert Schildwache Glynda Nal'Shea in Auberdine über Eure Erkenntnisse.", sourceObjectiveStatus = "unverified-source-field" }
quests[4812] = { id = 4812, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wenn das Wasser fließt", description = "Benutzt diese leere Phiole und füllt hier in Auberdine Mondbrunnenwasser hinein. Solch mächtige Magie sollte einen Hinweis auf die Zusammensetzung des Kristalls liefern. Zu diesem Zweck gießt Ihr etwas Flüssigkeit über den Kristall; alles Weitere sollte sich dann von selbst ergeben.\n\nWenn ich auch nicht erwarte, dass Euch etwas Böses zustoßen könnte, möchte ich dennoch, dass Ihr vorsichtig seid. Über uns im Osten liegt der Teufelswald; falls dieser Kristall mit jenem Ort verbunden ist, wie ich es vermute, könnte sich das als sehr gefährlich erweisen.", sourceObjective = "Füllt die leere Wasserröhre am Mondbrunnen von Auberdine und untersucht dann den roten Kristall an der östlichen Bergkette von Dunkelküste.", sourceObjectiveStatus = "unverified-source-field" }
quests[4813] = { id = 4813, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Fragmente im Inneren", description = "Das Mondbrunnenwasser hat enthüllt, dass im Inneren des Kristalls einige kleine Knochenfragmente sowie ein Teil eines Kieferknochens eingebettet sind. Der Kieferknochen scheint menschlich zu sein, aber um Klarheit darüber zu gewinnen, müsste man den Kristall aufbrechen - eine Leistung, die sogar für die stärkste Magie schier unmöglich erscheint.\n\nDa Ihr die gestellte Aufgabe erfüllt habt, bleibt nur noch, Schildwache Glynda Nal'Shea in Auberdine Bericht zu erstatten.", sourceObjective = "Informiert Schildwache Glynda Nal'Shea in Auberdine über Eure Erkenntnisse.", sourceObjectiveStatus = "unverified-source-field" }
quests[4821] = { id = 4821, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fremdartiges Ei", description = "Es wurde ein Gerücht über ein fremdartiges Ei hier in Tausend Nadeln in Umlauf gebracht. Diejenigen, die dieses Ei gesehen haben, konnten aber nicht nahe genug herankommen, um es ausführlich zu untersuchen. Schlangen bewachen das Ei, als wäre es eines ihrer eigenen.\n\nIch möchte, dass Ihr dieses fremdartige Ei sucht und es mir bringt, damit ich es untersuchen kann. Berichten zufolge soll sich das Ei in einem Schlangenbau befinden, aber es gibt mehrere Schlangenbaue entlang des Fußes der Klippenwand südlich und nordöstlich des Freiwindpostens.", sourceObjective = "Bringt Hagar Blitzhuf am Freiwindposten das fremdartige Ei.", sourceObjectiveStatus = "unverified-source-field" }
quests[4822] = { id = 4822, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lecker Eis", description = "EISCREME! Oh, könnt Ihr mir bitte, bitte, bitte etwas Eiscreme besorgen? Am liebsten mag ich Erdbeere und es gibt einfach kein besseres Erdbeereis als das von Tigule und Foror. Das ist mein liebstes Eis auf der ganzen Welt!\n\nFrüher gab es das immer auf der Rennstrecke in der Schimmernden Ebene, aber ich habe mal gehört, dass man es jetzt auch in der Stadt kaufen kann. Kriege ich bitte eins? Bitte? Am liebsten Tigules und Forors Eiscreme.", sourceObjective = "Besorgt für Euren Schützling etwas Erdbeereis. Der Kleine scheint die Marke 'Tigules und Forors Eiscreme' zu bevorzugen.", sourceObjectiveStatus = "unverified-source-field" }
quests[4841] = { id = 4841, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Befriedung der Zentauren", description = "{name}, ich flehe Euch an, diese Zentauren zur Strecke zu bringen. Sie sollen den Zorn unserer Rache spüren. Greift das Zentaurenlager im Norden des Freiwindpostens an! Lasst den Zorn Eure Hand führen!", sourceObjective = "Tötet 12 Späher der Galak, 10 Zänker der Galak sowie 6 Windjäger der Galak und kehrt dann zu Klippenbehüter Langhorn am Freiwindposten zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[4842] = { id = 4842, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sonderbare Quellen", description = "Also mal ehrlich, es gibt hier in Winterquell zwar keine Vulkane, aber ich glaube, dass es ein paar viel gefährlichere Ursachen für diese heißen Quellen gibt...\n\nTja, Ihr möchtet Euch das bestimmt lieber mit eigenen Augen ansehen. Ihr müsst dazu ganz Winterquell durchqueren und ganz nach Süden reisen. Wenn die Luft irgendwie stickig und schwül wird und sich der Himmel verdunkelt, habt Ihr gefunden, was ich für die Ursache der heißen Quellen halte.\n\nSeht es Euch an. Ich bin sicher, dass Ihr mit einer Menge Fragen zurückkehren werdet.", sourceObjective = "Befolgt Donova Schneewehs Anweisungen und meldet Euch dann wieder bei ihr.", sourceObjectiveStatus = "unverified-source-field" }
quests[4861] = { id = 4861, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wütende Wildekin", description = "Hallo, <Bursche/Mädchen>! Ein paar blutrünstige Wildekin haben mich aus meinem Lager im südlichen Winterquell vertrieben! Nun, ich schätze, ich bin irgendetwas zu nahe gekommen, das die Wildekin bewachen.\n\nIch hab es gerade noch geschafft, mit heiler Haut davonzukommen, aber ich fürchte, einer meiner Freunde hatte nicht so viel Glück. Würde es Euch wohl etwas ausmachen, Euch der Gefahr durch die Wildekin zu stellen und zum Lager zu gehen? Ich brauche unbedingt meine Vorräte und hätte auch gern das Amulett zurück, das ich gestern an der Ausgrabungsstätte zu Tage gefördert habe.", sourceObjective = "Findet Jaron Steinschleifers ruiniertes Lager samt dessen Vorräten im südlichen Winterquell.", sourceObjectiveStatus = "unverified-source-field" }
quests[4862] = { id = 4862, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Be-Öh-Es-Eh", description = "Ob Ihr es glaubt oder nicht, da draußen gibt es Leute, die gutes Geld selbst für die übelsten der abgerichteten Bestien ausgeben würden!\n\nIch würde ja Bijou zur Spitze schicken, um ein paar dieser Spitzenspinneneier zu sammeln, aber ich habe seit Wochen nichts mehr von ihr gehört. Vielleicht könnt Ihr mir helfen?\n\nIch sag Euch was, {name}. Geht zur Schwarzfelsspitze und sammelt ein paar Spitzenspinneneier für mich. Bringt sie mir, dann werde ich Euch nicht nur etwas Bargeld geben, sondern auch eines der Viecher für Euch abrichten!", sourceObjective = "Reist zur Schwarzfelsspitze und sammelt 15 Spitzenspinneneier für Kibler.\n\nLogischerweise müsstet Ihr diese Eier in der Nähe von Spinnen finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[4863] = { id = 4863, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wütende Wildekin", description = "Ihr seht Euch um und könnt nichts entdecken, was Jaron wohl noch brauchen könnte. Ihr stellt jedoch fest, dass die Kiste, die Ihr fandet, aufgebrochen wurde, als ob es die Wildekin darauf abgesehen hatten...\n\nAls Ihr nach Osten blickt, erkennt Ihr den vagen Umriss eines zurückgelassenen Wagens. Vielleicht findet Ihr Jarons Sachen ja dort. Nachsehen kann nicht schaden.", sourceObjective = "Sucht Jaron Steinschleifers zerstörten Wagen.", sourceObjectiveStatus = "unverified-source-field" }
quests[4864] = { id = 4864, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wütende Wildekin", description = "Nachdem Ihr den Inhalt des Kastens inspiziert habt, befindet Ihr, dass Jaron die Werkzeuge und anderen Gegenstände darin sicher gebrauchen könnte. Von dem Amulett fehlt jedoch jede Spur.\n\nDie Wildekin scheinen die Landstriche nördlich und östlich von hier zu bewohnen, also beschließt Ihr, dass Euer nächster Schritt sein wird, die Kreaturen aufzustöbern und das Amulett von ihnen einzufordern.", sourceObjective = "Klaubt Jarons Vorräte aus dem Schnee und sucht dann die Wildekin, die das Amulett gestohlen haben, von dem Jaron gesprochen hatte.\n\nBringt Jaron Steinschleifer in der Lodge in Winterquell dessen Vorräte und das blaugefiederte Amulett.", sourceObjectiveStatus = "unverified-source-field" }
quests[4865] = { id = 4865, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wilde Schlange", description = "Wenn ich es nicht mit eigenen Augen gesehen hätte, würde ich es nie für möglich gehalten haben. Die Rache kam nach Tausend Nadeln!\n\n<Hagar wischt sich den Schweiß von der Stirn.>\n\n{name}, Ihr müsst Euch beeilen! Geht sofort los und sucht Motega Feuermähne auf. Ihr findet ihn im Weißgipfelposten nordwestlich des Freiwindpostens, entlang der Straße. Er wird wissen, was zu tun ist!", sourceObjective = "Berichtet Motega Feuermähne von Euren Entdeckungen. Zu finden ist er im Weißgipfelposten in Tausend Nadeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[4866] = { id = 4866, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Muttermilch", description = "Das dürfte eines der stärksten Gifte der Welt sein, {race}!\n\nIch habe bei meinen Ausflügen zur Spitze immer wieder gehört, wie die Schwarzfelsorcs davon sprachen, wie tödlich es sei. Sie nennen es 'Muttermilch', benannt nach Mutter Glimmernetz, der großen, grausamen Spinne in der Listspinnerhöhle.\n\nAlso, das müsst Ihr mir besorgen: eine frische Probe dieser Milch, die durch EURE Adern fließt. Mir einfach nur die Giftdrüse zu bringen, wäre nicht genug! Bringt sie dazu, Euch zu vergiften, und kommt dann zu mir zurück!\n\nDann... kann ich Euch melken!\n\n<Reibt sich voller Vorfreude die Hände.>", sourceObjective = "Ihr findet Mutter Glimmernetz im Herzen der Schwarzfelsspitze. Kämpft mit ihr und bringt sie dazu, Euch zu vergiften. Es kann gut sein, dass Ihr sie sogar töten müsst. Kehrt zum struppigen John zurück, sobald Ihr vergiftet seid, damit er Euch 'melken' kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[4867] = { id = 4867, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Urok Schreckensbote", description = "Argh! Das Sprechen fällt schwer!\n\nNehmt diese Notiz! Holt mir mein Mojo.", sourceObjective = "Lest Waroshs Rolle. Bringt Waroshs Mojo zu Warosh.", sourceObjectiveStatus = "unverified-source-field" }
quests[4881] = { id = 4881, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auftragsmordplan", description = "Der Tauren Kanati Grauwolke war so dreist, in Tausend Nadeln ein Jägerlager aufzuschlagen. Wir müssen ihn töten, damit dieses Jägerlager und alle, die ihm möglicherweise folgen, verschwinden. Wir werden uns dem kleinen Posten südwestlich des Großen Aufzugs nähern.", sourceObjective = "Warnt Kanati Grauwolke am Weißgipfelposten, dass man vorhat, ihn zu töten.", sourceObjectiveStatus = "unverified-source-field" }
quests[4882] = { id = 4882, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheimnisse bewahren", description = "Ihr seid Euch unsicher bezüglich der Bedeutung der Halskette, die vom Hals des gerade erschlagenen Wildekin stammt. Sie glüht hell, verblasst und wird wieder hell.\n\nTrull Scheiterbann kann Euch vielleicht mehr darüber sagen, da er über sehr großes Wissen über die Wildekin verfügt. Vielleicht solltet Ihr ihn darüber befragen.", sourceObjective = "Bringt Trull Scheiterbann beim Blutgiftposten das blaugefiederte Amulett.", sourceObjectiveStatus = "unverified-source-field" }
quests[4883] = { id = 4883, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheimnisse bewahren", description = "Auch wenn ich viel über die Eulenbestien weiß, die Ihr in Winterquell erledigt habt, bin ich in der Magie, die sie wirken, nicht wirklich bewandert. Aber ich glaube, dass ich jemanden kenne, der die Kette untersuchen und Euch sagen könnte, was es ist.\n\nNara Wildmähne in Donnerfels ist eine Expertin auf diesem Gebiet; trefft Euch mit ihr. Viel Glück, {name}.", sourceObjective = "Bringt Nara Wildmähne das blaugefiederte Amulett.", sourceObjectiveStatus = "unverified-source-field" }
quests[4901] = { id = 4901, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wächter des Altars", description = "Ganz oben auf dem Grat liegt das, was ich für einen Altar der Göttin Elune halte. Soweit ich das sagen kann, müssen wir in jeder Höhle fünf Fackeln anzünden. Dann können wir den eigentlichen Altar erreichen.\n\nIch habe einige der Zauberformeln übersetzt, die in den Stein der alten Ruinen von Kel'Theril geritzt sind. Meiner Meinung nach sind sie der Schlüssel, mit dem man den Altar freigeben kann. Ich brauche Eure Hilfe dabei, alle Fackeln anzuzünden, während ich den Zauber rezitiere.\n\nWenn wir Erfolg haben, könnt Ihr Erelas unseren Fund melden!", sourceObjective = "Schützt Ranshalla, während sie versucht, den Altar von Elune wieder zu aktivieren. Berichtet Erelas Himmelsbern in Rut'theran von Eurem Fund.", sourceObjectiveStatus = "unverified-source-field" }
quests[4902] = { id = 4902, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wildekin von Elune", description = "Das ist faszinierend!\n\nIch habe mich immer gefragt, was die Wahrheit ist... Nun, Ihr müsst dieses Wissen auf alle Fälle teilen! Geht sofort zum Erzdruiden Fandral Hirschhaupt. Ihr werdet ihn in Darnassus im Zirkel des Cenarius antreffen. Erklärt ihm, was passiert ist, genau so wie Ihr es mir erzählt habt. Ich bin sicher, es wird ihn ebenso interessieren!\n\nDas sind wichtige Informationen, {name}!", sourceObjective = "Sprecht mit Erzdruide Fandral Hirschhaupt in Darnassus.", sourceObjectiveStatus = "unverified-source-field" }
quests[4903] = { id = 4903, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Befehl des Kriegsherrn", description = "Auf Befehl von Kriegsherr Bluthauer müssen die nachfolgenden Bewohner der Schwarzfelsspitze eliminiert werden:\n\nDie aufgeblasene Bedrohung, Hochlord Omokk.\n\nDer grausame und erbarmungslose Troll Kriegsmeister Voone.\n\nOberanführer Wyrmthalak, Zuchtmeister der geringen Stadt.\n\nDes Weiteren müsst Ihr alle wichtigen Dokumente zurückbringen, die Ihr möglicherweise findet.\n\nSeid erfolgreich und macht Euch Ehre.\n\nVersagt und seid vergessen.", sourceObjective = "Tötet Hochlord Omokk, Kriegsmeister Voone und Oberanführer Wyrmthalak. Findet die wichtigen Schwarzfelsdokumente. Kehrt zum Kriegsherrn Bluthauer nach Kargath zurück, sobald Ihr diese Mission erledigt habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[4904] = { id = 4904, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Endlich frei", description = "Arnak glaubt, dass wir heiraten werden… aber nachdem ich seinen Antrag abgelehnt hatte, kehrte er in der Nacht zurück und entführte mich. Mein Bruder wollte ihn aufhalten, aber Arnak war einfach zu stark. Er... er tötete meinen Bruder, dann brachte er mich hierher. Mein armer Bruder...\n\n{name}, würdet Ihr mich wohl vom Düsterwolkengipfel hinab geleiten? Bitte... ich muss zu Thalia zurückkehren! Sie macht sich bestimmt große Sorgen um mich.", sourceObjective = "Geleitet Lakota Windweise vom Düsterwolkengipfel hinab und sprecht dann im Freiwindposten mit Thalia Bernhaut.", sourceObjectiveStatus = "unverified-source-field" }
quests[4906] = { id = 4906, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weitere Verderbnis", description = "Ein weiterer Satyrstützpunkt unter der Leitung des grausamen Xavaric bedroht den Teufelswald im Norden. Die elenden Verräter und Schwindler zehren von der Verderbnis der im Teufelswald heimischen Kreaturen.\n\nXavathras und seine Diener waren nur Teil eines größeren Plans - ein Mondbrunnen sollte verderbt werden und Xavaric sollte dann die Beute bekommen.\n\nDa Xavathras jetzt beseitigt ist, solltet Ihr diese Aufgabe beenden, {name}. Geht nach Norden und besiegt Xavaric.", sourceObjective = "Eridan Blauwind im Teufelswald möchte, dass Ihr Xavaric sowie 8 Jadefeuerhöllenrufer, 8 Jadefeuerverräter und 8 Jadefeuerschwindler tötet. Kehrt zu Eridan zurück, sobald Ihr die Aufgabe erfüllt habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[4907] = { id = 4907, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tinkee Kesseldampf", description = "Hallo, {name}. Erinnert Ihr Euch an Tinkee Kesseldampf? Tja, sie erinnert sich jedenfalls an Euch! Sie schickte mir eine Nachricht, dass ich nach Euch Ausschau halten soll... sie braucht nämlich nochmals Eure Hilfe. Ich glaube, es hat was mit ihren Drachenstudien zu tun.\n\nIhr solltet mit ihr sprechen. Sie ist in der Brennenden Steppe, beim Flammenkamm.", sourceObjective = "Sprecht mit Tinkee Kesseldampf auf dem Flammenkamm in der Brennenden Steppe.", sourceObjectiveStatus = "unverified-source-field" }
quests[4921] = { id = 4921, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In der Schlacht vermisst", description = "Wir wurden getrennt, als wir in einem kleinen Taurenlager gemeinsam kämpften - sie hat drei Borstennacken im Alleingang bezwungen. Aber dann waren sie plötzlich in der Überzahl. Ich lockte ein paar fort, dann sah ich, wie sie von Neuankömmlingen überwältigt wurde. Rasend vor Zorn stellte ich mich meinen Feinden, aber da es derer so viele waren, ging ich schon bald zu Boden.\n\nIch kam im Zelt eines Taurendruiden zu mir, der meine Wunden versorgte - er kam zufällig die Goldstraße entlang, als ich fiel.\n\nBitte, {class}, sucht nach einem Lebenszeichen von meiner Frau.", sourceObjective = "Sucht Mankriks Frau und kehrt dann zu ihm in die Siedlung beim Wegekreuz zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[4941] = { id = 4941, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Etriggs Weisheit", description = "Rend lebt?\n\nUnmöglich!\n\nEr soll doch schon vor Jahrzehnten getötet worden sein.\n\nBittet Etrigg, seine Weisheit mit Euch zu teilen, {name}. Niemand kennt den Schwarzfelsklan besser als er, und wenn es wahr ist, was hier geschrieben steht, muss Etrigg davon in Kenntnis gesetzt werden. Niemandem sollte das Recht auf Vergeltung versagt werden.\n\nIhr findet ihn in Orgrimmar.\n\nWenn Ihr mit Etrigg gesprochen habt, beratet Euch mit dem Kriegshäuptling, um von ihm zu erfahren, was er bezüglich dieses Problems zu unternehmen gedenkt.", sourceObjective = "Sprecht mit Etrigg in Orgrimmar. Wenn Ihr die Angelegenheit mit Etrigg besprochen habt, bittet Thrall um Rat.\n\nIhr erinnert Euch, dass Ihr Etrigg in Thralls Gemächern gesehen habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[4961] = { id = 4961, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Säuberung der Kugel von Orahil", description = "Ah, eine Beschwörerkugel - sie muss die Quelle der Besudelung sein. Wir müssen erst den Dämon darin exorzieren, wenn Ihr sie benutzen wollt. Das ist ein Klacks für mich.\n\nIhr habt die schwere Aufgabe. Ihr müsst den Dämon töten, sobald ich ihn freigesetzt habe.\n\nUnd Ihr müsst Euch beeilen. Wenn Ihr zu lange braucht, kehrt er in die Kugel zurück und wir müssen von vorn anfangen!\n\nAlso macht Euch bereit, {name}. Bereitet Eure stärksten Zauber vor, habt Eure Tränke parat und holt einen Freund, wenn Ihr einen habt. Denn das hier wird nicht angenehm.", sourceObjective = "Tötet den Dämon der Kugel und sprecht dann mit Tabetha.", sourceObjectiveStatus = "unverified-source-field" }
quests[4962] = { id = 4962, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Splitter eines Teufelshundes", description = "Ihr seid also entschlossen, die Seele eines Teufelshundes zu fangen, gut.\n\nNehmt diesen Rubin - mit ihm könnt Ihr die Seele der Kreatur einfangen. Er funktioniert auf ähnliche Weise wie die Zauber, die Ihr bereits kennt: Wenn die Kreatur dem Tode nahe ist, benutzt den Edelstein, er sollte dann den Rest für Euch erledigen.\n\nIch schlage vor, dass Ihr nach Desolace geht und versucht, dort eines Teufelshundes habhaft zu werden. Die sollten geeignet sein.\n\nWenn Ihr Erfolg hattet, bringt den gefangenen Geist und Euren Rubin zu Menara.", sourceObjective = "Nehmt den Teufelsrubin und benutzt ihn bei einem der Teufelshunde von Desolace. Wenn Ihr Erfolg hattet, bringt Menara Leerbringer im Brachland den eingekerkerten Teufelshundgeist und den Teufelsrubin.", sourceObjectiveStatus = "unverified-source-field" }
quests[4963] = { id = 4963, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Splitter einer Höllenbestie", description = "Ihr seid also entschlossen, die Seele einer Höllenbestie zu fangen, gut.\n\nNehmt diesen Smaragd - mit ihm könnt Ihr die Seele der Kreatur einfangen. Er funktioniert auf ähnliche Weise wie die Zauber, die Ihr bereits kennt: Wenn die Kreatur dem Tode nahe ist, benutzt den Edelstein, er sollte dann den Rest für Euch erledigen.\n\nIch schlage vor, dass Ihr nach Desolace geht und versucht, dort einer Höllenbestie habhaft zu werden. Die sollten geeignet sein.\n\nWenn Ihr Erfolg hattet, bringt den gefangenen Geist und Euren Smaragd zu Menara.", sourceObjective = "Nehmt den Infussmaragd und benutzt ihn bei einer der Höllenbestien von Desolace. Wenn Ihr Erfolg hattet, bringt Menara Leerbringer im Brachland den eingekerkerten Höllenbestiengeist und den Infussmaragd.", sourceObjectiveStatus = "unverified-source-field" }
quests[4964] = { id = 4964, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die fertiggestellte Kugel von Dar'Orahil", description = "Ich werde sofort mit der Arbeit an Eurer Kugel beginnen und Euren neuen Dämon darin einschließen. Wenn ich damit fertig bin, könnt Ihr entscheiden, ob Ihr ihn lieber in Form eines Stabs oder einer Kugel hättet. Ich fand es schon immer wichtig, dafür zu sorgen, dass jeder Hexenmeister die richtige Waffe bekommt...Ich wüsste nicht, warum ich jetzt mit dieser Praxis aufhören sollte.", sourceObjective = "Wartet, bis Menara Leerbringer die Kugel von Dar'Orahil fertig gestellt hat, und sprecht dann noch einmal mit ihr.", sourceObjectiveStatus = "unverified-source-field" }
quests[4965] = { id = 4965, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wissen der Kugel von Orahil", description = "Schön, schön, schön... Es ist eine Freude zu sehen, wie Eure Macht wächst, {name}. Ich würde sagen, dass Ihr bald bereit seid, im Brachland mit Menara Leerbringer zu sprechen. Falls Ihr noch nie mit ihr gesprochen habt, dann lasst mich Euch sagen, dass ich wohl keinen zweiten Experten wie sie kenne, der so geschickt im Anfertigen von Gegenständen - insbesondere Kugeln - ist, in denen man sogar einen Dämon einkerkern kann, damit er einem einfach und bequem zu Diensten ist.\n\nFalls Ihr interessiert seid, begebt Euch zu Strahads Turm oberhalb von Ratschet im Brachland, dort findet Ihr sie.", sourceObjective = "Sprecht mit Menara Leerbringer im Brachland.", sourceObjectiveStatus = "unverified-source-field" }
quests[4966] = { id = 4966, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kanati Grauwolke schützen", description = "Es könnte allerdings noch viel mehr Zentauren geben, als ich dachte, deshalb bitte ich Euch, {name}, zusammen mit mir gegen diese gemeinen Auftragsmörder zu kämpfen.", sourceObjective = "Beschützt Kanati Grauwolke vor den Angriffen der Zentauren.", sourceObjectiveStatus = "unverified-source-field" }
quests[4967] = { id = 4967, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wissen der Kugel von Orahil", description = "Immer noch derselbe Dummkopf... und immer noch auf der Suche nach Dingen der Sterblichen. Ja, es mag Euch arrogant erscheinen, wie ich zu Euch spreche. Ihr steht vor mir und ich muss lachen. Ihr seid jämmerlich!\n\nAber was ich denke, zählt nicht. Es zählt nur, was jene denken, die gewillt sind, sich mit Euch abzugeben! Und obwohl ich anderer Ansicht bin, sind jene, die über ein gewisses Maß an Macht gebieten, der Meinung, dass Ihr mehr verdient.\n\nWenn es das ist, wonach Ihr trachtet, solltet Ihr mit Menara Leerbringer im Turm oberhalb von Ratschet sprechen. Ich glaube, Ihr habt sie vor geraumer Zeit schon einmal getroffen.", sourceObjective = "Sprecht mit Menara Leerbringer im Brachland.", sourceObjectiveStatus = "unverified-source-field" }
quests[4968] = { id = 4968, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wissen der Kugel von Orahil", description = "Hmm, Ihr habt es also bis hierher geschafft... das ist wahrhaft erstaunlich. Ich dachte, die Verderbnis durch die Kanalisierung des Arkanen hätte sich mittlerweile in Eure Seele geschlichen und Euch in den Wahnsinn getrieben. Sollen wir versuchen, Euch noch ein bisschen weiter aufzubauen?\n\nWenn Ihr Eure Fertigkeiten auf die Probe stellen wollt, sprecht mit Menara Leerbringer. Sie ist in Strahads Turm oberhalb von Ratschet zu finden. Sie wird Euch leiten.", sourceObjective = "Sprecht mit Menara Leerbringer im Brachland.", sourceObjectiveStatus = "unverified-source-field" }
quests[4969] = { id = 4969, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wissen der Kugel von Orahil", description = "Haha! Das habt Ihr sehr gut gemacht, {class}.\n\nFrüher oder später werden sich selbst Höllenbestien und Schreckenslords vor Euch in den Staub werfen!\n\nAber bis dahin müsst Ihr Euch noch auf die Waffen verlassen, die von Sterblichen geschaffen wurden.\n\nIhr scheint bereit zu sein für ein weiteres solches Werk, und wenn Ihr möchtet, würde Menara Leerbringer mit Euch sprechen! Sie ist in der Nähe von Strahads Turm zu finden, der oberhalb der Hafenstadt Ratschet steht. Geht dorthin, wenn Ihr bereit seid.", sourceObjective = "Sprecht mit Menara Leerbringer im Brachland.", sourceObjectiveStatus = "unverified-source-field" }
quests[4970] = { id = 4970, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frostsäblerverpflegung", description = "Wenn Ihr Euch beweisen wollt, könnt Ihr eine sehr einfache, aber sehr wichtige Aufgabe erledigen.\n\nSammelt Fleisch von den Schimären und den Splitterzahnbären in diesem Gebiet. Bringt es mir, dann kann ich damit die Frostsäbler füttern, die gerade ausgebildet werden.", sourceObjective = "Sammelt 5 Splitterzahnfleischstücke und 5 Fleischstücke einer Eiswindschimäre für Rivern Frostwind in Winterquell.", sourceObjectiveStatus = "unverified-source-field" }
quests[4971] = { id = 4971, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Frage der Zeit", description = "Die Zeitlinie in Andorhal wurde durch eine finstere Kraft verfälscht - wahrscheinlich durch die Geißel! Ich kann versuchen, das Verstreichen der Zeit hier in den Griff zu bekommen und den Schaden zu beheben, aber dazu benötige ich Hilfe, damit ich dabei nicht gestört werde.\n\nTemporale Parasiten - Aas, das sich von den Strängen des veränderten Zeitflusses ernährt, sucht jetzt die Silos von Andorhal heim. Man kann sie nur an der blau pulsierenden Verzerrung erkennen. Sie behindern meine Weissagungen. Bitte helft mir, {name}, indem Ihr diesen Temporalversetzer benutzt, um diese Parasiten auszurotten.", sourceObjective = "Benutzt den Temporalversetzer in der Nähe eines der Silos von Andorhal, um die temporalen Parasiten aufzuspüren.\n\nTötet 10 temporale Parasiten und bringt dann den Temporalversetzer zu Chromie im Gasthaus Andorhal in den Westlichen Pestländern.", sourceObjectiveStatus = "unverified-source-field" }
quests[4972] = { id = 4972, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tempus fugit", description = "Ihr müsst für mich in die jenseits dieses Raumes liegende Welt gelangen, {name}. Lasst es mich Euch erklären.\n\nIhr seht, dass dieser Raum hier anders ist als der Rest von Andorhal. Mein Drachenschwarm agiert auf verschiedene Weise und in vielen verschiedenen Zeitlinien. Um den in Andorhal angerichteten Schaden zu beheben, handle ich jetzt von einer anderen Zeitlinie aus, um sie nicht allzu sehr zu kontaminieren. Um diese Arbeit fortzusetzen, benötige ich Zeitobjekte, die aus einer Zeit stammen, bevor die Seuche auftrat. Ihr findet sie in Schließkassetten in den Ruinen der Gebäude, die einst diese stolze Stadt waren.", sourceObjective = "Sucht 5 Uhren von Andorhal, die in Schließkassetten überall im Schutt der Stadt zu finden sind. Kehrt mit ihnen zu Chromie ins Gasthaus Andorhal in den Westlichen Pestländern zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[4973] = { id = 4973, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tempus fugit", description = "Falls Ihr gewillt seid, mir noch einmal zu helfen, würde ich Eure Unterstützung dankbar annehmen. Ich nehme Euch gern weitere Uhren ab, die Ihr in den Ruinen von Andorhal findet. Sie helfen mir sicherlich dabei, das Gleichgewicht gegen die unbekannte bösartige Kraft zu erhalten, die hier mit der Zeitlinie herumspielt.\n\nIm Austausch für diese Uhren werde ich Euch einen anderen Gegenstand geben, der sich, wie ich vermute, in der Zukunft für Euch als von großem Wert erweisen wird.", sourceObjective = "Sucht 5 Uhren von Andorhal in den Ruinen der Stadt und bringt sie Chromie im Gasthaus Andorhal in den Westlichen Pestländern.", sourceObjectiveStatus = "unverified-source-field" }
quests[4974] = { id = 4974, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Für die Horde!", description = "Nur weil der schwarze Drachenschwarm hinter ihm steht, wagt Rend es, solche Ansprüche zu stellen.\n\nIhr, {name}, müsst einen Weg finden, die Hallen des Aufstiegs zu durchqueren. Dahinter findet Ihr den 'Kriegshäuptling' Rend Schwarzfaust. Ihr müsst ihn vernichten... FÜR DIE HORDE!\n\n<Thrall schlägt mit der Faust auf seinen Thron.>\n\nWenn Ihr meine Gemächer das nächste Mal betretet, werdet Ihr seinen Kopf triumphierend in die Höhe halten und ihn Eurem Kriegshäuptling präsentieren. Gelingt Euch das, wird man Euch als Held der Horde ehren.", sourceObjective = "Begebt Euch zur Schwarzfelsspitze und tötet den Kriegshäuptling Rend Schwarzfaust. Nehmt seinen Kopf und kehrt nach Orgrimmar zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[4975] = { id = 4975, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die fertiggestellte Kugel von Noh'Orahil", description = "Ich werde sofort mit der Arbeit an Eurer Kugel beginnen und Euren neuen Dämon darin einschließen. Wenn ich damit fertig bin, könnt Ihr entscheiden, ob Ihr ihn lieber in Form eines Stabs oder einer Kugel hättet. Ich fand es schon immer wichtig, dafür zu sorgen, dass jeder Hexenmeister die richtige Waffe bekommt...Ich wüsste nicht, warum ich jetzt mit dieser Praxis aufhören sollte.", sourceObjective = "Wartet, bis Menara Leerbringer die Kugel von Noh'Orahil fertig gestellt hat, und sprecht dann noch einmal mit ihr.", sourceObjectiveStatus = "unverified-source-field" }
quests[4976] = { id = 4976, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ablieferung der gesäuberten Kugel", description = "Bringt die gesäuberte Kugel zurück zu Menara nach Ratschet, {name}. Grüßt sie von mir und passt auf Euch auf. Ich hoffe wirklich, dass Ihr der Versuchung und der Verderbnis widerstehen könnt, die Euch auf Eurem Weg sicherlich begleiten werden.\n\nViel Glück.", sourceObjective = "Bringt die gesäuberte Höllenkugel zu Menara Leerbringer ins Brachland.", sourceObjectiveStatus = "unverified-source-field" }
quests[4981] = { id = 4981, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Agentin Bijou", description = "Trau niemals einem Goblin. Darauf läuft es doch hinaus, {name}.\n\nSie heißt Bijou und ist eine unserer unzuverlässigsten Agentinnen. Ich habe herausgefunden, dass sie für irgendeinen zwielichtigen Tierhändler namens Kibler außerhalb der Brennenden Steppe gearbeitet hat - sie hat uns schlicht und ergreifend hintergangen. Und was noch schlimmer ist, sie hat Gelder der Horde veruntreut, um ihre Machenschaften zu finanzieren.\n\nIch will, dass man sie mir lebend bringt!\n\nZuletzt wurde sie beim Betreten der Schwarzfelsspitze gesehen. Findet sie und bringt sie her.\n\nUnd lasst Euch bloß nicht von ihr umgarnen, {name}.", sourceObjective = "Begebt Euch zur Schwarzfelsspitze und findet heraus, was aus Bijou geworden ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[4982] = { id = 4982, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bijous Habseligkeiten", description = "Nachts, wenn dieser Ort hier nur leicht bewacht ist, schleiche ich durch die Stadt, mache mir Notizen und schreibe alles auf, was für das KEK strategisch nützlich sein könnte.\n\nLetzte Nacht ist allerdings etwas fürchterlich schief gegangen. Ich bin über einen Stolperdraht getappt und habe einen Alarm ausgelöst. Also habe ich mein Spionagezeug versteckt und bin auf Tauchstation gegangen! Leider kann ich nicht zurück, um meine Ausrüstung zu holen. Sie haben die Patrouillen verdoppelt und verdreifacht! All diese Informationen sind verloren.\n\nHolt mir meine Habseligkeiten, dann kehre ich freiwillig zum KEK zurück.", sourceObjective = "Sucht Bijous Habseligkeiten und bringt sie ihr. Ihr erinnert Euch daran, dass sie erwähnte, ihre Sachen auf der untersten Ebene der Stadt versteckt zu haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[4983] = { id = 4983, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bijous Aufklärungsbericht", description = "Bringt Lexlort diesen Bericht. Er wird meinen Namen reinwaschen und dem KEK bestimmt einen strategischen Vorteil gegenüber diesen Orcs verschaffen.\n\nIch soll mit Euch kommen? Dafür habe ich noch viel zu viel zu tun. Geht jetzt, diese Berichte werden gebraucht, je eher, desto besser!", sourceObjective = "Bringt Bijous Aufklärungsbericht zu Großmeister Lexlort nach Kargath.", sourceObjectiveStatus = "unverified-source-field" }
quests[4984] = { id = 4984, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Tierwelt leidet auch", description = "Allein konnte ich nicht viel tun, um die Geißel zu bezwingen. Aber ich kam dennoch hierher, um zu versuchen, den an der Natur angerichteten Schaden zu lindern. Die Tiere leiden unter der Seuche, die das Land noch immer plagt, und finden weder Gnade noch Frieden. Ich bitte Euch fortzusetzen, was ich hier nicht beenden konnte.\n\nEs gibt für diese leidenden Tiere keine Rettung, nur eine gnädige und sanfte Erlösung. Sucht die kranken Wölfe auf, die sich hier in der Nähe befinden, und tötet sie. Bitte, {name}, macht ihrem Leiden ein Ende - Ihr würdet damit auch meinen Kummer lindern.", sourceObjective = "Tötet 8 kranke Wölfe und kehrt dann zu Mulgris Tiefenfurt auf dem Trostlosen Feld in den Westlichen Pestländern zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[4985] = { id = 4985, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Tierwelt leidet auch", description = "Östlich von hier, etwa da, wo die Östlichen Pestländer beginnen, streiften einst stolze und herrliche Grizzlys durch das Land. Die von der Geißel freigesetzte Seuche hat auch auf diese Wildtiere übergegriffen. Jetzt ziehen sie durchs Land und leiden sehr, während ihre Muskeln steif werden und ihr Fell und Fleisch langsam verrotten.\n\nIch bitte Euch, auch sie von ihrem Elend zu erlösen. Das einzige Heilmittel für sie ist ein schneller Tod, beigebracht durch Eure Hand.", sourceObjective = "Tötet 8 kranke Grizzlys und kehrt dann zu Mulgris Tiefenfurt auf dem Trostlosen Feld in den Westlichen Pestländern zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[4986] = { id = 4986, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glyphenverzierter Eichenast", description = "Die leblose Hand des Tauren hält einen erstaunlich gesund aussehenden Eichenast umklammert. Als Ihr den Ast untersucht, entdeckt Ihr Glyphen druidischer Art, die in die Rinde geritzt sind.\n\nIhr nehmt den Ast und stellt fest, dass er sich warm anfühlt. Viel wärmer, als er sich anfühlen sollte. Vor Eurem inneren Auge erscheint das Bild des Baums von Teldrassil - genau gesagt von Darnassus - und die Worte \"Zirkel des Cenarius\" liegen Euch auf der Zunge. Es scheint, als hätte man dem Ast die Information mitgegeben wohin er zu bringen sei.", sourceObjective = "Nach der Magie zu urteilen, mit der der glyphenverzierte Eichenast erfüllt ist, hatte der Taurendruide wohl gewollt, dass Ihr den Ast zum Zirkel des Cenarius nach Darnassus bringt. Bittet einen der Druiden dort um Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[4987] = { id = 4987, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glyphed Oaken Branch" }
quests[5001] = { id = 5001, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bijous Habseligkeiten", description = "Normalerweise gebe ich mich nicht mit Euresgleichen ab, {race}, aber mir scheint, ich stecke hier in einer Zwickmühle. Wisst Ihr, meine Mission hier ist für die Horde von allergrößter Wichtigkeit. Die Informationen, die ich hier gesammelt habe, betreffen jedoch auch das Wohlergehen der Allianz. Ihr könnt mir glauben, ich bin wahrlich kein Freund der Allianz, aber die Gefahr durch den Schwarzfelsklan ist größer als nur ein Haufen Orcs.\n\nIhr helft mir, meine Habseligkeiten zu finden, dann helfe ich Euch mit ein paar Informationen aus, die sich für Euresgleichen als nützlich erweisen könnten.\n\nAbgemacht?", sourceObjective = "Sucht Bijous Habseligkeiten und bringt sie ihr. Viel Glück!", sourceObjectiveStatus = "unverified-source-field" }
quests[5002] = { id = 5002, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nachricht an Maxwell", description = "Ich bin ein Goblin, der zu seinem Wort steht, {race}. Und jetzt hört gut zu.\n\nDiese Orcs werden vom schwarzen Drachenschwarm vor allem als Packesel und Kanonenfutter missbraucht!\n\nIhr wahrer Anführer ist kein Geringerer als Nefarian, die Brut von Todessschwinge. Ich habe auch den Aufenthaltsort der Untergebenen von Nefarian in diesem Teil der Zitadelle entdeckt.\n\nBringt diese Karte zu Marschall Maxwell in der Brennenden Steppe. Auf ihr ist der Aufenthaltsort dieser Teufelskreaturen eingezeichnet, um es einfacher zu machen.", sourceObjective = "Begebt Euch in die Brennende Steppe und leitet Bijous Informationen an Marschall Maxwell weiter.", sourceObjectiveStatus = "unverified-source-field" }
quests[5021] = { id = 5021, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Besser spät als nie", description = "\"Das Paket muss ausgeliefert werden... sonst bin ich hier gefangen!\"\n\nWie ein Flüstern zieht das Wehklagen einer verängstigten Frau durch das Haus. In einer Ecke im oberen Stockwerk kauert eine weibliche, geisterhafte Gestalt. Sie scheint sich ihrer Umgebung nicht ganz gewahr zu sein und ist sich Eurer nur vage bewusst.\n\n\"Seid Ihr hier, um mein Paket auszuliefern? Bitte, bevor es noch viel schlimmer wird! Ich wollte hier wegreiten. Es sollte immer noch bei meinem Pferd sein... oder komme ich zu spät?\"", sourceObjective = "Das wilde Gebrabbel der Geisterfrau deutete darauf hin, dass sie ein Paket ausliefern musste. Sie behauptete, dass es dort war, wo auch ihr Pferd war. Darüber, wo das Pferd jetzt ist oder wohin das Paket ausgeliefert werden muss, sagt der Geist nichts.", sourceObjectiveStatus = "unverified-source-field" }
quests[5022] = { id = 5022, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Besser spät als nie", description = "Ihr hebt das Paket auf und wischt eine dünne Schicht aus Staub und Schmutz ab, mit der es bedeckt ist. Es ist mit hastig hingekritzelter Schrift an eine Emma Teufelsstein in Sturmwind adressiert; die Auslieferung des Pakets war für einen Tag vor über vier Jahren geplant.\n\nOb Emma Teufelsstein überhaupt noch lebt, ist nicht klar. Aber man weiß, dass im Rathaus von Sturmwind Unterlagen über die Bevölkerung der Stadt aufbewahrt werden. Sie werden von den königlichen Disponenten des Volkszählungsbüros von Sturmwind verwaltet.", sourceObjective = "Wendet Euch an die königlichen Disponenten von Sturmwind, um etwas über den Aufenthaltsort von Emma Teufelsstein herauszufinden. Normalerweise findet sich ein Volkszählungsbeamter im Rathaus.", sourceObjectiveStatus = "unverified-source-field" }
quests[5023] = { id = 5023, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Better Late Than Never" }
quests[5041] = { id = 5041, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorräte für das Wegekreuz", description = "Was auch immer im Südlichen Brachland geschehen ist, es hat einige der Stacheleberstämme in unsere Richtung getrieben. Insbesondere die vertriebenen Klingenmähnen werden immer verzweifelter und ihre Angriffe werden immer waghalsiger. Allein diese Woche habe ich schon zwei Karawanen verloren!\n\nUnsere Krieger am Wegekreuz warten händeringend auf diese Vorräte und ich habe nicht vor, zuzulassen, dass diese Stacheleber sich dank dieser Missetaten fettfressen können. Findet die vermissten Vorratskisten und bringt sie zu mir. Ich würde die Stacheleberhütten südlich von hier entlang des Flusses durchsuchen.", sourceObjective = "Sammelt 5 Vorratskisten des Wegekreuzes in der Höhle der Klingenmähnen.", progress = "Wie läuft Eure Suche nach den Vorräten, {name}? Ich schätze, die Stacheleber werden unter Eurer Kraft schnell fallen.", completion = "Haha! Danke, {name}! Das wird uns höchst dienlich sein. Ich werde diese Vorräte verpacken und sie sofort auf den Weg zum Wegekreuz schicken.", sourceObjectiveStatus = "unverified-source-field" }
quests[5042] = { id = 5042, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Agamaggans Kraft" }
quests[5043] = { id = 5043, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Agamaggans Beweglichkeit" }
quests[5044] = { id = 5044, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weisheit von Agamaggan" }
quests[5045] = { id = 5045, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Steigerung des Geistes" }
quests[5046] = { id = 5046, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Klingenhaut" }
quests[5047] = { id = 5047, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Finkle Einhorn, zu Euren Diensten!", description = "Ihr findet Malyfous Düsterhammer in der Ewigen Warte, {class}. Sagt ihm, dass Finkle absolut in Ordnung ist und dass der Anzug perfekt funktioniert.\n\nDann gebt ihm dies:\n\n<Finkle gibt Euch ein leuchtendes Fleischstück.>\n\nIch riss es aus den Innereien des Viechs während meines 'Urlaubs.'\n\nIch wette Malyfous könnte Euch eine recht genaue Einschätzung dessen geben, was er mit Teilen eines solchen Monsters tun kann!\n\nOh, ich schätze Ihr wisst nicht, wo die Ewige Warte ist, was? Geht nach Winterquell, <Bursche/meine Dame>!", sourceObjective = "Sprecht mit Malyfous Düsterhammer in der Ewigen Warte.", sourceObjectiveStatus = "unverified-source-field" }
quests[5048] = { id = 5048, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Emma die Nette", description = "Sie ist ein bisschen zänkisch und vielleicht nicht so ganz richtig im Kopf... aber diese Akten deuten darauf hin, dass die alte Emma zu den Informationen passt, die wir über Emma Teufelsstein haben.\n\nVielleicht habt Ihr die alte Emma durch die Stadt streifen sehen... sie redet mit sich selbst, meistens sinnloses Geplapper. Sie tut aber nichts und niemandem weh, also lassen die Leute sie meist gewähren.\n\nAlles in allem würde ich sagen, dass die alte Emma tatsächlich Emma Teufelsstein ist. Ihr könntet sie fragen, ob ihr Nachname Teufelsstein ist.", sourceObjective = "Sucht die alte Emma in Sturmwind und findet heraus, ob sie tatsächlich Emma Teufelsstein ist. Wenn sie es ist, dann möchte sie vielleicht das Paket haben, das Janice Teufelsstein für sie gepackt hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[5049] = { id = 5049, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Jammer des Jeremiah", description = "Nach den Informationen, die ich finden konnte, ist die Person, die Ihr sucht - und der vorgesehene Empfänger des Pakets -, Jeremiah Payson, der Kakerlakenverkäufer von Unterstadt.\n\nIch war immer der Meinung, dass es einer besonderen Gabe bedarf, um... Kakerlaken zu verkaufen. Zweifellos seid Ihr jetzt auf einer recht epischen Reise, {class}. Ich werde Euch Euren weltverändernden Bestrebungen überlassen. Erlaubt mir aber, ein Teil Eures Meisterwerks zu sein und zu enthüllen, dass er sich in der Nähe der Bank aufhält und unter einem der Gehwege herumkriecht.", sourceObjective = "Sucht Jeremiah Payson in Unterstadt und findet heraus, ob er tatsächlich Jeremiah Teufelsstein ist. Wenn er es ist, dann möchte er vielleicht das Paket haben, das Janice Teufelsstein für ihn gepackt hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[5050] = { id = 5050, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glücksbringer", description = "Es scheint, dass ich bei Euch falsch lag, {name}, und dafür schulde ich Euch eine Entschuldigung. Meine Schwester hat einige persönliche Dinge geschickt, einschließlich, was witzig genug ist, die Urkunde zum Teufelssteinfeld. Ich denke, ich werde im Moment darauf verzichten, Anspruch darauf geltend zu machen.\n\nWenn der Geist meiner Schwester weiterhin an den Hof gebunden ist und keine Ruhe finden kann, bitte... könntet Ihr dies wohl zu ihr bringen? Es ist die Hälfte eines Glücksbringers, den sie einst hatte. Die andere Hälfte hatte ihr Ehemann.\n\nVielleicht wird sie ihren Frieden finden, wenn sie weiß, dass ich diese Dinge habe.", sourceObjective = "Bringt Janice Teufelsstein in den Westlichen Pestländern die Hälfte ihres Glücksbringers zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[5051] = { id = 5051, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zwei Hälften vereint", description = "Der arme Geist plappert weiter:\n\n\"Mir ist so kalt, John. Bring mir deinen Glücksbringer und wir werden vereint sein! Schnell, John, bevor die Seuche uns in grauenhafte Bestien verwandelt! Ich kann dich nicht sehen, John... aber ich weiß, dass du nah bist. Ich fühle dich in meiner Nähe.\"\n\nVielleicht solltet Ihr die zweite Hälfte des Glücksbringers suchen und das Amulett wieder zusammensetzen... es könnte sein, dass der Geist von Janice Teufelsstein genau das sucht.", sourceObjective = "Sucht auf dem Teufelssteinfeld in den Westlichen Pestländern nach der anderen Hälfte des Glücksbringers und setzt ihn wieder zusammen.\n\nGebt den Glücksbringer Janice Teufelsstein auf dem Teufelssteinfeld in den Westlichen Pestländern.", sourceObjectiveStatus = "unverified-source-field" }
quests[5052] = { id = 5052, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blutsplitter von Agamaggan", description = "Zusammen mit diesen Dornen wirkte sich das Blut <schnaubt> auf andere Aspekte der Erde aus: blutrote Steine gemischt mit anderen Mineralien. Die Borstennacken graben diese Splitter aus und tragen sie als Totems <schnaubt> für Kraft im Kampf und als Totems für ihre Magie. <schnaubt>\n\nIch kenne die Geheimnisse dieser Magie.\n\nBringt Quetschzahn einen dieser Blutsplitter, um zu zeigen, dass Ihr verstanden habt. Bringt Quetschzahn viele dieser Splitter und er wird Euch mit Stachelebermagie segnen - der Magie von Agamaggan! <schnaubt>", sourceObjective = "Bringt Quetschzahn im Camp Taurajo im Brachland einen Blutsplitter.\n\nSammelt weitere Blutsplitter, wenn Ihr von ihm mit Agamaggans Macht gesegnet werden möchtet.", sourceObjectiveStatus = "unverified-source-field" }
quests[5054] = { id = 5054, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ursius von den Splitterzahnbären", description = "In den schneebedeckten Bergen von Winterquell pirscht sich ein geschickter Jäger an seine Beute an... Ich spreche vom Splitterzahnbären Ursius, einer flinken und schlauen Bestie.\n\nIch schicke Euch nun gegen ihn. Er zieht durch die wogenden Hügel im Nordwesten der Ewigen Warte. Findet und jagt ihn, bevor er Eure Absicht erkennt.\n\nAlle, die bisher gegen Ursius gezogen sind, haben schnell herausgefunden, dass sie die Beute waren und er der Jäger. Also seht Euch vor.", sourceObjective = "Storm Schattenhuf in der Ewigen Warte in Winterquell möchte, dass Ihr Ursius tötet.", sourceObjectiveStatus = "unverified-source-field" }
quests[5055] = { id = 5055, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brumeran von den Eiswindschimären", description = "Geschickt und schlau gleitet Brumeran leise über die schneebedeckte Landschaft des südlichen Winterquell. Lasst Euch aber nicht von Ihrem graziösen Auftreten verleiten zu glauben, dass sie harmlos sei. Alle, die ihren Weg kreuzen, bezahlen einen hohen Preis dafür und häufig mit ihrem eigenen Leben.\n\nSucht Brumeran von den Eiswindschimären. Besiegt sie und kehrt dann wieder zu mir zurück.", sourceObjective = "Storm Schattenhuf in der Ewigen Warte in Winterquell möchte, dass Ihr Brumeran tötet.", sourceObjectiveStatus = "unverified-source-field" }
quests[5056] = { id = 5056, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shy-Rotam", description = "Im nördlichen Winterquell sammeln sich große Katzen rund um einen großen Orientierungspunkt, dem Frostsäblerfelsen. Die Anführerin dieser Katzen ist unter dem Namen Shy-Rotam bekannt. Wenn Ihr die Matriarchin der Frostsäbler besiegen würdet, würde Euch das großen Respekt in den Augen der anderen einbringen, {race}.\n\nGeht erneut nach Winterquell und sammelt dort hochheiliges Fleisch von den Frostsäblern. Sucht den Stein von Shy-Rotam und legt das Fleisch dort ab. Wenn Ihr es dort platziert, ruft das Shy-Rotam herbei... und sie wird kochen vor Wut.\n\nWappnet Euch vor ihrem Zorn und besiegt sie.", sourceObjective = "Storm Schattenhuf in der Ewigen Warte in Winterquell möchte, dass Ihr Shy-Rotam besiegt.", sourceObjectiveStatus = "unverified-source-field" }
quests[5057] = { id = 5057, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frühere Abenteuer", description = "Schon bevor Ihr mit mir spracht, {name}, habe ich von Euren Abenteuern gehört... dass Ihr den unerschütterlichen Willen habt, Euch selbst zu beweisen, und dass Ihr als {class} außerordentliche Fähigkeiten besitzt. Und nun weiß ich, dass diese Dinge wahr sind.\n\nWer wie Ihr herausragt, ist der Anerkennung würdig. Bringt diesen Gutschein zu einem Freund von mir in Donnerfels namens Melor Steinhuf. Ich bin sicher, dass er sich an Euch und das, was Ihr vor so langer Zeit erreicht habt, erinnern wird. Sprecht mit ihm über Eure jüngsten Siege und vergesst nicht, was Ihr heute erreicht habt.", sourceObjective = "Bringt Storm Schattenhufs Gutschein zu Melor Steinhuf in Donnerfels.", sourceObjectiveStatus = "unverified-source-field" }
quests[5058] = { id = 5058, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frau Dalsons Tagebuch" }
quests[5059] = { id = 5059, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weggeschlossen" }
quests[5060] = { id = 5060, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weggeschlossen" }
quests[5061] = { id = 5061, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wassergestalt", description = "Ihr habt die notwendigen Lektionen gemeistert, die alle jungen Druiden lernen, bevor sie einen Wasseraspekt annehmen können. Kehrt jetzt zu Eurem Lehrer Mathrengyl Bärenfährte nach Darnassus zurück. Zeigt ihm Euren Anhänger und beweist ihm damit, dass Ihr bereit seid zu lernen, was er Euch lehren kann. Er wird Eure Ausbildung abschließen und Euch ermöglichen, eins mit dem Wasser zu werden.\n\nAuf Wiedersehen. Wir werden uns wieder sprechen.", sourceObjective = "Kehrt nach Darnassus zurück und zeigt Mathrengyl Bärenfährte den Anhänger des Seelöwen.", sourceObjectiveStatus = "unverified-source-field" }
quests[5062] = { id = 5062, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hochheiliges Feuer", description = "Arikara ist eine tödliche Kreatur, die schnell beseitigt werden muss. Um sie zur Strecke zu bringen, müsst Ihr das hochheilige Feuer des Lebens anzünden - so wird Arikara beschworen.\n\nGeht nun und holt eine seltene Pflanze, die Brandpulveragave. Wenn Ihr genug Agaven gesammelt habt, sucht den Rat von Magatha Grimmtotem auf der Anhöhe der Ältesten in Donnerfels. Sie ist eine mächtige Schamanin, die die Agavenpflanze verzaubern kann, um ein Pulver zu erzeugen, das das Feuer entzünden kann.\n\nReist in Richtung Osten zum Siedenden Teich und sammelt Brandpulveragaven.", sourceObjective = "Sammelt 10 Scheffel Brandpulveragaven und beratet Euch dann mit Magatha Grimmtotem auf der Anhöhe der Ältesten in Donnerfels.", sourceObjectiveStatus = "unverified-source-field" }
quests[5063] = { id = 5063, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kappe des Scharlachroten Wissenden", description = "Eine feinere Kappe werdet Ihr niemals sehen. Aus dem makellosen Balg der Bestie werden unsere Experten den phänomenalsten Hut schaffen, den ein Gaukler jemals zu tragen träumte!\n\nFünfzig Goldstücke zusammen mit den aufgeführten Gegenständen und Euer Kopf wird von der Kappe des Scharlachroten Wissenden geziert:\n\n*Einen makellosen Balg der Bestie.\n\n*Ausgefranste Monstrositätenstickereien.\n\n*Arkankristalle.\n\n*Verzauberter scharlachroter Faden.\n\nMERKT AUF!", sourceObjective = "Um die Kappe des scharlachroten Wissenden herzustellen, müsst Ihr die folgenden Dinge zu Malyfous Düsterhammer bringen: 1 makelloser Balg der Bestie; 5 ausgefranste Monstrositätenstickereien; 8 Arkankristalle; 5 verzauberte scharlachrote Fäden.\n\nIhr müsst außerdem 50 Goldstücke für die Herstellung des Gegenstandes zahlen.", sourceObjectiveStatus = "unverified-source-field" }
quests[5064] = { id = 5064, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grimmtotemspionage", description = "{name}, Ihr habt uns in der Vergangenheit gut gedient, sodass ich Euch jetzt eine wichtige Mission anvertraue. Der Grimmtotemklan plant etwas, das niemand wissen soll. Drei Agenten unbekannter Herkunft wurden gesehen, wie sie die Grimmtotem in den vergangenen Wochen besuchten. Wir haben entdeckt, dass diese geheimnisvollen Botschaften im Düsterwolkengipfel in verschiedenen Truhen verwahrt werden.\n\n{name}, wenn Ihr bei dieser gefährlichen Mission erfolgreich seid, werde ich Euch entsprechend belohnen.", sourceObjective = "Sucht die drei geheimen Notizen im Düsterwolkengipfel und bringt sie zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[5065] = { id = 5065, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die verlorenen Schrifttafeln von Mosh'aru", description = "Der Troll, mit dem Ihr gesprochen habt, hat Euch nicht die Wahrheit gesagt. Die beiden Schrifttafeln, die Ihr für ihn erhalten habt, sprachen davon, die Essenz von Hakkar zu bewahren, aber an dieser Legende ist noch mehr. Ich habe sie lange studiert und herausgefunden, dass es sechs Schrifttafeln von Mosh'aru gibt, nicht zwei! Sechs!\n\nUnd ich fürchte, dass uns die Geheimnisse, die die anderen enthalten, nicht gefallen werden.\n\nSucht die dritte und vierte Schrifttafel von Mosh'aru. Sie befinden sich in den Östlichen Pestländern, im Besitz der Moosschindertrolle. Sucht sie und bringt sie mir.", sourceObjective = "Bringt Ausgrabungsleiter Eisenschuh in Tanaris die dritte und vierte Schrifttafel von Mosh'aru.", sourceObjectiveStatus = "unverified-source-field" }
quests[5066] = { id = 5066, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ruf zu den Waffen: Die Pestländer!", description = "Hört her, hört her! Alle Helden werden ersucht, aufzumerken!\n\nDas Königreich Sturmwind ruft zu den Waffen! Alle einsatzfähigen Individuen sind hiermit angehalten, gegen die dunkle Bedrohung durch die Geißel in den nördlichen Ländern der Östlichen Königreiche zu den Waffen zu greifen! Es gibt Gerüchte über neue Bedrohungen, die sich aus den Ruinen der Pestländer erheben!\n\nHelden der Welt... Sucht Kommandant Ashlam Ehrenschlag auf, der seinen Stützpunkt an der Zugwindspitze errichtet hat, nördlich des Alteracgebirges!", sourceObjective = "Sucht Kommandant Ashlam Ehrenschlag auf. Sein Stützpunkt befindet sich an der Zugwindspitze, nördlich des Alteracgebirges.", sourceObjectiveStatus = "unverified-source-field" }
quests[5067] = { id = 5067, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gamaschen von Arcana", description = "Wenn die Herstellung eines solchen Gegenstandes auch noch nie erfolgreich bewerkstelligt wurde, so wird sie doch für möglich erachtet - unter den richtigen Umständen.\n\nSollte der Sucher des Arkanums wünschen, Gamaschen mit immenser Kraft magiezuerfüllen, so muss er Folgendes suchen:\n\n*Einen makellosen Balg der Bestie.\n\n*Ausgefranste Monstrositätenstickereien.\n\n*Arkanitbarren.\n\n*Frostraunens Balsamierungsflüssigkeit.\n\nMERKT AUF!", sourceObjective = "Um die Gamaschen von Arcana herzustellen, müsst Ihr die folgenden Dinge zu Malyfous Düsterhammer bringen: 1 makelloser Balg der Bestie; 5 ausgefranste Monstrositätenstickereien; 5 Arkanitbarren; 5 Einheiten Frostraunens Balsamierungsflüssigkeit.\n\nIhr müsst außerdem 50 Goldstücke für die Herstellung des Gegenstandes zahlen.", sourceObjectiveStatus = "unverified-source-field" }
quests[5068] = { id = 5068, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brustplatte des Blutdurstes", description = "Es heißt, dass nur eine einzige Brustplatte des Blutdurstes jemals geschaffen wurde und dass sie für die legendäre Auftragsmörderin Garona gemacht wurde. Ob diese Welt jemals eine weitere sehen wird, ist zu bezweifeln.\n\nWie dem auch sei! Unsere meisterlichen Handwerker können den Gegenstand reproduzieren, wenn die notwendigen Komponenten vorhanden sind:\n\n*Ein makelloser Balg der Bestie.\n\n*Ausgefranste Monstrositätenstickereien.\n\n*Arkanitbarren.\n\n*Die Haut des Schattens.\n\nMERKT AUF!", sourceObjective = "Um die Brustplatte des Blutdurstes herzustellen, müsst Ihr die folgenden Dinge zu Malyfous Düsterhammer bringen: 1 makelloser Balg der Bestie; 10 ausgefranste Monstrositätenstickereien; 5 Arkanitbarren; 5 Häute des Schattens.\n\nIhr müsst außerdem 50 Goldstücke für die Herstellung des Gegenstandes zahlen.", sourceObjectiveStatus = "unverified-source-field" }
quests[5081] = { id = 5081, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maxwells Mission", description = "Diese Informationen füllen die Lücken in unseren sonst einwandfreien Geheimdienstdaten über die Schwarzfelsspitze.\n\nDer Angriff muss entscheidend sein, {name}.\n\nZuerst muss ihr Kriegsmeister, der Troll Voone, vernichtet werden. Ohne seine Kampfpläne werden die Schwarzfelsorcs im Chaos versinken.\n\nDann müsst Ihr den Ogerhochlord Omokk ausschalten. Die feigen Oger des Schwarzfels sind ohne seine Führungskraft machtlos.\n\nSchließlich noch der Oberanführer der Zitadelle: Wyrmthalak. Wenn Wyrmthalak tot ist, ist ihre zentrale Kommandoeinheit ohne Leitung.", sourceObjective = "Reist zur Schwarzfelsspitze und schaltet Kriegsmeister Voone, Hochlord Omokk und Oberanführer Wyrmthalak aus.", sourceObjectiveStatus = "unverified-source-field" }
quests[5082] = { id = 5082, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bedrohung durch die Winterfelle", description = "Ich kam nach Winterquell, um die Frostfeuerquellen zu untersuchen. Mir ist aufgefallen, dass das Wasser... merkwürdige Eigenschaften zu haben scheint. Ich konnte die Quelle aber noch nicht entdecken, und um die Wahrheit zu sagen, hatte ich in letzter Zeit durch die Furbolgs der Winterfelle einige Schwierigkeiten.\n\nSie scheinen von den Quellen angezogen zu werden, genau wie ich. Mittlerweile wachen sie extrem eifersüchtig über das Wasser und lassen mich nicht einmal in die Nähe der beiden größeren Quellen, die von hier aus im Norden liegen.\n\nIch würde meine Studien aber gern fortsetzen. Könntet Ihr mir wohl helfen?", sourceObjective = "Donova Schneeweh in Winterquell möchte, dass Ihr 8 Pfadfinder der Winterfelle, 8 Höhlenbehüter der Winterfelle und 8 Totemiker der Winterfelle erledigt.", sourceObjectiveStatus = "unverified-source-field" }
quests[5083] = { id = 5083, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feuerwasser der Winterfelle", description = "Diese Phiole, die Ihr bei den Winterfellfurbolgs aufgehoben habt, ist leer, aber Ihr könnt im Inneren ein paar Tropfen einer merkwürdigen grünen Flüssigkeit sehen; sie scheint fast zu glühen.\n\nIst es etwas Wichtiges?\n\nDonova Schneeweh könnte Euch wahrscheinlich mehr sagen, da sie nun schon einige Zeit bei den heißen Quellen in Winterquell lagert.", sourceObjective = "Bringt das leere Feuerwasserfläschchen zu Donova Schneeweh in Winterquell.", sourceObjectiveStatus = "unverified-source-field" }
quests[5084] = { id = 5084, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Verderbnis erliegen", description = "Diese grünliche Flüssigkeit... sie erinnert mich ein wenig an den Schlamm, den ich bei meiner Reise durch den Teufelswald sah. Und ich habe einige Läufer der Winterfelle gesehen, die die Furbolgs der Holzschlundfeste passierten... Vielleicht haben diese Dinge etwas mit dem Fläschchen zu tun, das Ihr gefunden habt, {name}.\n\nEs gibt eine große Gruppe Furbolgs direkt hinter der Holzschlundfeste im Teufelswald. Es ist der so genannte Stamm der Totenwaldfelle. Er wurde durch teuflische Energien verderbt und in den Wahnsinn getrieben. Warum seht Ihr Euch dort nicht um und schaut, ob Ihr Beweise für irgendwelche Beziehungen zwischen den Winterfellfurbolgs und den Totenwaldfellen findet?", sourceObjective = "Durchsucht das Furbolglager der Totenwaldfelle im nördlichen Teil des Teufelswalds nach einem Hinweis.", sourceObjectiveStatus = "unverified-source-field" }
quests[5085] = { id = 5085, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheimnisvoller Glibber", description = "Die grünliche Substanz in dem Kessel scheint der zu ähneln, die Ihr in dem Fläschchen gefunden habt. Dieses merkwürdige zähflüssige Zeug könnte genauso verderbt sein wie die Furbolgs, die es geschaffen haben...\n\nFalls die Winterfellfurbolgs es verwenden, bedeutet das, dass sie bald genauso verderbt sein werden wie der Stamm der Totenwaldfelle?\n\nEs wäre das Beste, Donova von Euren Funden zu berichten und ihr eine Probe aus dem Kessel mitzubringen.", sourceObjective = "Berichtet Donova Schneeweh von Euren Entdeckungen.", sourceObjectiveStatus = "unverified-source-field" }
quests[5086] = { id = 5086, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Toxinschrecken", description = "Ich habe die Probe untersucht, die Ihr mitgebracht habt. Ganz sicher bin ich mir nicht, aber ich glaube doch, dass sie Spuren von toxischen Elementen enthält. Die einzige Möglichkeit, das zu bestätigen, besteht darin, einige Proben als Vergleich zu sammeln.\n\nIch glaube, dass sich die Furbolgs der Totenwaldfelle diese Elemente möglicherweise von anderen verderbten Kreaturen im Teufelswald holen, vor allem von den Elementaren, die im Eisenwald leben und Toxinschrecken genannt werden.\n\nSammelt einige Proben zum Vergleich für mich. Aber seid vorsichtig: Es ist dort sehr gefährlich!", sourceObjective = "Sammelt 3 Toxinschreckentropfen für Donova Schneeweh in Winterquell.", sourceObjectiveStatus = "unverified-source-field" }
quests[5087] = { id = 5087, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Läufer der Winterfelle", description = "Sehr interessant, {name}...\n\nWenn diese toxische Substanz mit dem Wasser aus den heißen Quellen gemischt wird, verliert sie ihre Toxizität und behält lediglich die Fähigkeit zurück, Kreaturen vorübergehend zu beeinflussen, die sie einnehmen. Darum verteidigen die Winterfelle die heißen Quellen wohl so vehement - sie brauchen sie, um ihr Feuerwasser zu läutern.\n\nWir müssen das hier stoppen... den Kontakt zwischen den Winterfellen und den Totenwaldfellen abschneiden. Eine Gruppe von Läufern ist zwischen ihrem Dorf und dem Teufelswald unterwegs. Sucht und besiegt sie und stehlt ihre Lieferung.", sourceObjective = "Sucht die Läufer der Winterfelle und hindert sie daran, ihre Lieferung zum Lager der Winterfelle zu bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[5088] = { id = 5088, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arikara", description = "Bringt dieses aufbereitete und geläuterte Brandpulver nach Tausend Nadeln und werft es in das hochheilige Feuer des Lebens. Es befindet sich beim Düsterwolkengipfel auf einer isolierten Nadel, wo sie ihre Toten beerdigen.\n\nDie Verzauberung, die ich in das Brandpulver eingewoben habe, wird Arikara für Euch beschwören, {name}.\n\nIch fürchte, dass sie Cairne Bluthuf bedrohen könnte; die Lehren der Tauren haben sich zu sehr verändert und möglicherweise ist Arikara darüber erzürnt. Tut schnell etwas, bevor alles verloren ist, {class}!", sourceObjective = "Erschlagt Arikara. Bringt ihre Überreste und das Brandpulver zu Motega Feuermähne im Weißgipfelposten als Beweis für Eure Tat.", sourceObjectiveStatus = "unverified-source-field" }
quests[5089] = { id = 5089, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "General Drakkisaths Befehl", description = "Dem Kadaver der besiegten Schlange entnehmt Ihr etwas, das wie ein Schreiben von einiger Bedeutung aussieht. Es ist ein Brief des Vorgesetzten, General Drakkisath, bezüglich des Protokolls.\n\nEuer Instinkt sagt Euch, dass Ihr ihn zu Marschall Maxwell bringen solltet.", sourceObjective = "Bringt den Befehl von General Drakkisath zu Marschall Maxwell in der Brennenden Steppe.", sourceObjectiveStatus = "unverified-source-field" }
quests[5090] = { id = 5090, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ruf zu den Waffen: Die Pestländer!", description = "Hört her, hört her! Alle Helden werden ersucht, aufzumerken!\n\nDas Königreich Sturmwind ruft zu den Waffen! Alle einsatzfähigen Individuen sind hiermit angehalten, gegen die dunkle Bedrohung durch die Geißel in den nördlichen Ländern der Östlichen Königreiche zu den Waffen zu greifen! Es gibt Gerüchte über neue Bedrohungen, die sich aus den Ruinen der Pestländer erheben!\n\nHelden der Welt... Sucht Kommandant Ashlam Ehrenschlag auf, der seinen Stützpunkt an der Zugwindspitze errichtet hat, nördlich des Alteracgebirges!", sourceObjective = "Sucht Kommandant Ashlam Ehrenschlag auf. Sein Stützpunkt befindet sich an der Zugwindspitze, nördlich des Alteracgebirges.", sourceObjectiveStatus = "unverified-source-field" }
quests[5091] = { id = 5091, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ruf zu den Waffen: Die Pestländer!", description = "Hört her, hört her! Alle Helden werden ersucht, aufzumerken!\n\nDas Königreich Sturmwind ruft zu den Waffen! Alle einsatzfähigen Individuen sind hiermit angehalten, gegen die dunkle Bedrohung durch die Geißel in den nördlichen Ländern der Östlichen Königreiche zu den Waffen zu greifen! Es gibt Gerüchte über neue Bedrohungen, die sich aus den Ruinen der Pestländer erheben!\n\nHelden der Welt... Sucht Kommandant Ashlam Ehrenschlag auf, der seinen Stützpunkt an der Zugwindspitze errichtet hat, nördlich des Alteracgebirges!", sourceObjective = "Sucht Kommandant Ashlam Ehrenschlag auf. Sein Stützpunkt befindet sich an der Zugwindspitze, nördlich des Alteracgebirges.", sourceObjectiveStatus = "unverified-source-field" }
quests[5092] = { id = 5092, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Weg räumen", description = "Da die westlichen und nördlichen Straßen in die Stadt von Andorhal gut befestigt sind, habe ich vor, über die weniger gut verteidigte östliche Straße anzugreifen. Die Geißel verlässt sich auf den Puffer von Untoten, die Trauerhügel heimsuchen, als erste Verteidigungslinie. Wenn wir nach Andorhal vordringen wollen, müssen wir es über Trauerhügel tun.\n\nEure erste Aufgabe besteht darin, den Weg durch Trauerhügel zu säubern. Dünnt die Masse der Skelette und Ghule aus, die das Gebiet heimsuchen. Meldet Euch wieder bei mir, wenn das erledigt ist!", sourceObjective = "Tötet 10 Skelettschinder und 10 sabbernde Ghule in Trauerhügel.\n\nKehrt zu Kommandant Ashlam Ehrenschlag an der Zugwindspitze in den Westlichen Pestländern zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[5093] = { id = 5093, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ruf zu den Waffen: Die Pestländer!", description = "Helden der Welt, höret mich - die Horde ruft zum schnellen Aufmarsch!\n\nAlle einsatzfähigen Personen werden zu den Waffen gerufen, um gegen die Geißel zu ziehen! Es gibt Gerüchte über neue Bedrohungen, die sich aus den Ruinen der Östlichen Königreiche erheben! Sie lauern östlich von Unterstadt, in den nördlichen Ausläufern der Länder, die als Pestländer bekannt sind!\n\nHelden der Welt - sucht Hochexekutor Derrington auf. Er hat seinen Stützpunkt am Bollwerk östlich von Tirisfal aufgeschlagen!", sourceObjective = "Sucht Hochexekutor Derrington auf. Sein Stützpunk befindet sich am Bollwerk, östlich von Tirisfal und Unterstadt.", sourceObjectiveStatus = "unverified-source-field" }
quests[5094] = { id = 5094, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ruf zu den Waffen: Die Pestländer!", description = "Helden der Welt, höret mich - die Horde ruft zum schnellen Aufmarsch!\n\nAlle einsatzfähigen Personen werden zu den Waffen gerufen, um gegen die Geißel zu ziehen! Es gibt Gerüchte über neue Bedrohungen, die sich aus den Ruinen der Östlichen Königreiche erheben! Sie lauern östlich von Unterstadt, in den nördlichen Ausläufern der Länder, die als Pestländer bekannt sind!\n\nHelden der Welt - sucht Hochexekutor Derrington auf. Er hat seinen Stützpunkt am Bollwerk östlich von Tirisfal aufgeschlagen!", sourceObjective = "Sucht Hochexekutor Derrington auf. Sein Stützpunk befindet sich am Bollwerk, östlich von Tirisfal und Unterstadt.", sourceObjectiveStatus = "unverified-source-field" }
quests[5095] = { id = 5095, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ruf zu den Waffen: Die Pestländer!", description = "Ihr Helden dieser Welt, höret mich - die Horde ruft zum schnellen Aufmarsch!\n\nAlle einsatzfähigen Personen werden zu den Waffen gerufen, um gegen die Geißel zu ziehen! Es gibt Gerüchte über neue Bedrohungen, die sich aus den Ruinen der Östlichen Königreiche erheben! Sie lauern östlich von Unterstadt, in den nördlichen Ausläufern der Länder, die als Pestländer bekannt sind!\n\nZögert nicht lange, ihr Helden! Sucht Hochexekutor Derrington auf! Er hat seinen Stützpunkt am Bollwerk östlich von Tirisfal aufgeschlagen.", sourceObjective = "Sucht Hochexekutor Derrington auf. Sein Stützpunkt befindet sich am Bollwerk, östlich von Tirisfal und Unterstadt.", sourceObjectiveStatus = "unverified-source-field" }
quests[5096] = { id = 5096, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scharlachrote Ablenkung", description = "Vor Andorhal müssen wir die Bedrohung durch den anrückenden Scharlachroten Kreuzzug von Herdweiler niederschlagen. Dessen Lager wurde zwischen dem Teufelssteinfeld und Dalsons Tränenfeld aufgeschlagen, wodurch wir gleichzeitig einen Konflikt mit der Geißel und dem Kreuzzug riskieren müssen.\n\nMein Plan ist, sie gegeneinander auszuspielen, indem wir Euch schicken, um das Kommandozelt zu zerstören, das sie errichtet haben. Benutzt dazu die Flaschenflammen aus dieser Kiste mit Brandsätzen. Sobald es vernichtet ist, richtet Ihr dieses Banner der Geißel bei dem Zelt auf. Mit etwas Glück werden sie uns ignorieren und sich auf Rache gegen die Geißel konzentrieren.", sourceObjective = "Zieht zum Basislager des Scharlachroten Kreuzzugs zwischen dem Teufelssteinfeld und Dalsons Tränenfeld und zerstört sein Kommandozelt.\n\nLasst das Banner der Geißel im Lager wehen und kehrt dann zu Hochexekutor Derrington am Bollwerk in den Westlichen Pestländern zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[5097] = { id = 5097, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Turm um Turm", description = "Durch die Verwendung eines magischen Gegenstandes, einer Signalfackel, können wir Ziele unserer Wahl für künftige Aktionen durch unsere Truppen markieren. Was das angeht, glauben wir, dass die Geißel die Wachtürme von Andorhal nutzt, um die Bewegungen ihrer Truppen zu kontrollieren.\n\nEure Mission: Durchbrecht die Verteidigung von Andorhal, um Signalfackeln an allen vier Wachtürmen zu platzieren. Ihr müsst im Eingang eines jeden Turmes stehen, um das Signal zu platzieren; es wird dann den Turm markieren. Die Signalfackel hat nur fünf Ladungen, nutzt sie also weise!", sourceObjective = "Markiert mit der Signalfackel jeden Turm in Andorhal; Ihr müsst im Eingang jedes Turmes stehen, um ihn erfolgreich zu markieren.\n\nWenn alle vier Türme markiert sind, bringt Ihr die Signalfackel zu Kommandant Ashlam Ehrenschlag an der Zugwindspitze in den Westlichen Pestländern zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[5098] = { id = 5098, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Turm um Turm", description = "Durch die Verwendung eines magischen Gegenstandes, einer Signalfackel, können wir Ziele unserer Wahl für künftige Aktionen durch unsere Truppen markieren. Was das angeht, glauben wir, dass die Geißel die Wachtürme von Andorhal nutzt, um die Bewegungen ihrer Truppen zu kontrollieren.\n\nEure Mission: Durchbrecht die Verteidigung von Andorhal, um Signalfackeln an allen vier Wachtürmen zu platzieren. Ihr müsst im Eingang eines jeden Turmes stehen, um das Signal zu platzieren; es wird dann den Turm markieren. Die Signalfackel hat nur fünf Ladungen, nutzt sie also weise!", sourceObjective = "Markiert mit der Signalfackel jeden Turm in Andorhal; Ihr müsst im Eingang jedes Turmes stehen, um ihn erfolgreich zu markieren.\n\nWenn alle vier Türme markiert sind, bringt Ihr die Signalfackel zu Hochexekutor Derrington am Bollwerk in den Westlichen Pestländern, zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[5102] = { id = 5102, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "General Drakkisaths Niedergang", description = "Wir kämpfen an zwei Fronten gegen diese Biester: Von unserer Hauptstadt Sturmwind aus bekämpfen wir sie von innen, und hier, in der Brennenden Steppe, tragen wir den Kampf an ihre Türschwelle. Wir müssen wachsam sein, {name}. Niemand soll von unserem Zorn verschont werden, da keiner der Unseren verschont wurde, als der Feind bei unseren Heimen und Familien zuschlug.\n\nFindet diesen General Drakkisath und erledigt ihn!\n\nDie Aufgabe ist sicherlich nicht einfach, aber die Belohnungen werden großartig sein.", sourceObjective = "Begebt Euch zur Schwarzfelsspitze und schaltet General Drakkisath aus.", sourceObjectiveStatus = "unverified-source-field" }
quests[5103] = { id = 5103, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heißer, feuriger Tod", description = "Das Einzige, was von diesem Menschen übrig geblieben ist, sind einige verkohlte Knochen. Er scheint in Armeslänge dessen gestorben zu sein, hinter dem er her war - ungebrannten Plattenstulpen.\n\nVielleicht solltet Ihr die Stulpen nehmen und aus dem Feuer verschwinden?", sourceObjective = "Jemand auf dieser Welt muss doch wissen, was mit diesen Stulpen zu tun ist. Viel Glück!", sourceObjectiveStatus = "unverified-source-field" }
quests[5121] = { id = 5121, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oberhäuptling der Winterfelle", description = "Wir wissen leider immer noch nicht, warum die Furbolgs diese merkwürdige Substanz einnehmen. Aber ich glaube, es wäre das Beste, das zu unterbinden, bevor es ausufert.\n\nDie Furbolgs der Winterfelle sind normalerweise kein aggressiver Stamm und diese Änderung ihres Verhaltens führt mich zu der Annahme, dass sie Befehle ihres Häuptlings ausführen. Wir werden wohl den Schaden, der bereits angerichtet ist, nicht mehr beheben können, aber ich denke, wenn ihr Anführer erledigt ist, wird es zumindest nicht schlimmer werden.\n\nBegebt Euch nach Osten zum Lager der Winterfelle.", sourceObjective = "Donova Schneeweh in Winterquell möchte, dass Ihr den Oberhäuptling der Winterfelle besiegt.", sourceObjectiveStatus = "unverified-source-field" }
quests[5122] = { id = 5122, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Medaillon des Glaubens" }
quests[5123] = { id = 5123, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das letzte Stück", description = "Das Logbuch, das Ihr bei dem Oberhäuptling gefunden habt, scheint recht ausführlich zu sein, aber nachdem Ihr einige Seiten durchgesehen habt, stellt Ihr fest, dass Ihr den Text nicht lesen könnt. Die Zeichen sind so kunstlos und schlecht geformt, dass Ihr nicht sicher seid, ob überhaupt jemand sie lesen kann.\n\nAber vielleicht kann Donova Euch sagen, was sie bedeuten...", sourceObjective = "Bringt das kunstlos geschriebene Logbuch zu Donova Schneeweh in Winterquell.", sourceObjectiveStatus = "unverified-source-field" }
quests[5124] = { id = 5124, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feurige Plattenstulpen", description = "Beim Barte Thaurissans!\n\nWo habt Ihr sie gefunden?\n\nNoch wichtiger: Seid Ihr bereit, Euch von ihnen zu trennen? Natürlich würde ich solch eine noble Geste belohnen.\n\nIch sag Euch was, {name}. Wenn Ihr mir diese ungebrannten Stulpen gebt, werde ich Euch beibringen, wie Ihr selbst welche herstellen könnt. Ihr müsst nur die Teile für mich besorgen, damit ich das genaue Rezept benutzen kann.\n\nAbgemacht?\n\nHier ist die Liste dessen, was ich benötige. Ich werde das nicht-verzauberte Thorium selbst übernehmen, da Ihr ja die Stulpen liefert.", sourceObjective = "Bringt Malyfous Düsterhammer 6 verzauberte Thoriumbarren, 2 Essenzen des Feuers und 4 Sternrubine. Ihr müsst außerdem Eure ungebrannten Plattenstulpen abgeben.", sourceObjectiveStatus = "unverified-source-field" }
quests[5125] = { id = 5125, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aurius' Abrechnung" }
quests[5126] = { id = 5126, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lorax' Geschichte", description = "Der Satyr wandert auf und ab und spricht mit sich selbst. Möchtet Ihr ihn ansprechen?", sourceObjective = "Sprecht mit Lorax. Hört, was er zu sagen hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[5127] = { id = 5127, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Dämonenschmiede", description = "Lorax macht Geschäfte, aber er akzeptiert sie nicht von unbedeutenden Sterblichen.\n\nEinen Handel kann ich aber mit Euch machen... nehmt diese Pike, sie ist mit mächtigen Fel-Energien getränkt. Wenn Ihr Goraluk Hammerbruch findet, erschlagt ihn und treibt diese Pike durch sein sterbendes Herz. Er hat seine Seele verschachert und daher werde ich seine Seele bekommen. Bringt die Pike und die Brustplatte zurück, die der Dieb gestohlen hat, und ich werde Euch das beibringen, was er lernen sollte.", sourceObjective = "Begebt Euch zur Schwarzfelsspitze und sucht Goraluk Hammerbruch. Erschlagt ihn und wendet dann die blutbefleckte Pike auf seine Leiche an. Nachdem seine Seele abgesaugt wurde, wird die Pike seelenbefleckt sein.\n\nIhr müsst außerdem die ungeschmiedete runenbedeckte Brustplatte finden.\n\nBringt die seelenbefleckte Pike und die ungeschmiedete runenbedeckte Brustplate zu Lorax in Winterquell.", sourceObjectiveStatus = "unverified-source-field" }
quests[5128] = { id = 5128, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Worte des Oberhäuptlings", description = "Die Winterfelle sind für mich keine Bedrohung mehr, aber wenn Ihr immer noch herausfinden möchtet, was die Furbolgs dazu brachte, dieses merkwürdige Feuerwasser herzustellen und zu konsumieren, solltet Ihr Kelek Himmelshüter aufsuchen.\n\nEr gehört zu einer Gruppe, die als Smaragdkreis bekannt ist, Druiden, die sich ihrer Arbeit im Teufelswald widmen und das Land von der Verderbnis heilen.\n\nKelek hat viel Erfahrung mit den Furbolgs im Teufelswald und kann Euch vielleicht mehr über das Logbuch sagen.\n\nNochmals danke, {name}.", sourceObjective = "Bringt das kunstlos geschriebene Logbuch zu Kelek Himmelshüter im südlichen Teil des Teufelswalds.", sourceObjectiveStatus = "unverified-source-field" }
quests[5141] = { id = 5141, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drachenlederverarbeitung", description = "Drachenlederverarbeitung ist nicht einfach, aber sie ist sehr einträglich. Ich werde Euch beibringen, wie man diese feine Panzerrüstung fertigt, aber nur, wenn Ihr bestimmten Bedingungen zustimmt.\n\nMit der Wahl dieses Weges erklärt Ihr Euch einverstanden, niemals die Kunst der Elementarlederverarbeitung oder der Stammeslederverarbeitung zu erlernen. An der Spitze des Handwerks ist nur Platz für eine der drei. Des Weiteren werde ich eine Probe Eurer besten Arbeit aus dem Bereich der Skorpidrüstung benötigen. Schließlich benötige ich noch einen Beweis für Eure Fähigkeit, die Hauptzutat des Handwerks zu erlangen: Schuppen der Drachkin.", sourceObjective = "Bringt 2 feste Skorpidbrustplatten, 2 feste Skorpidhandschuhe und 10 Drachenschuppen zu Peter Galen in Azshara.\n\nWenn Ihr diese Aufgabe abschließt, werdet Ihr Zugang zur Kunst der Drachenlederverarbeitung erhalten.\n\nIhr könnt dann allerdings weder Elementarlederverarbeitung noch Stammeslederverarbeitung erlernen; seid also vorher sicher, dass dies der Weg ist, dem Ihr folgen wollt.", sourceObjectiveStatus = "unverified-source-field" }
quests[5142] = { id = 5142, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Klein-Pamela", description = "So viele von uns sind im Kampf von Darroheim gefallen. So viele starben... und noch Schlimmeres.\n\nAls die Schlacht begann, versteckte ich meine Nichte Pamela, und ich weiß nicht, was mit ihr geschehen ist. Ich bin nur ein wandernder Geist, aber mein Herz möchte dennoch Pamelas Schicksal kennen.\n\nBitte, {class}. Könnt Ihr nach Darroheim gehen und nach ihr suchen? Es liegt im Osten, hinter Gahrrons Trauerfeld.", sourceObjective = "Sucht in Darroheim nach Pamela Rotpfad.", sourceObjectiveStatus = "unverified-source-field" }
quests[5143] = { id = 5143, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stammeslederverarbeitung", description = "Um die Kunst der Stammeslederverarbeitung zu erlernen, müsst Ihr verstehen, wie urzeitlich die Natur wirklich ist; ich weiß, dass Ihr bereits die Kunst der Herstellung von Wildlederrüstungen gemeistert habt und ich bin bereit, Eure Ausbildung abzuschließen.\n\nDoch wisset dies, {class}: Durch die Wahl dieses Weges erklärt Ihr Euch einverstanden, niemals die Kunst der Drachenlederverarbeitung oder der Elementarlederverarbeitung zu erlernen. Ihr könnt nur eine dieser drei Künste erlernen. Bringt mir des Weiteren die feinsten Proben Eurer Wildlederrüstungen. Von diesem Punkt aus werden wir dann beginnen, an Eurem Können zu arbeiten.", sourceObjective = "Bringt eine Wildlederweste und einen Wildlederhelm zu Caryssia Jägermond in Feralas.\n\nWenn Ihr diese Aufgabe abschließt, werdet Ihr Zugang zur Kunst der Stammeslederverarbeitung erhalten.\n\nWenn Ihr diese Aufgabe abschließt, werdet Ihr allerdings weder Drachenlederverarbeitung noch Elementarlederverarbeitung erlernen können; seid also vorher sicher, dass dies der Weg ist, dem Ihr folgen wollt.", sourceObjectiveStatus = "unverified-source-field" }
quests[5144] = { id = 5144, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elementarlederverarbeitung", description = "Elementarlederverarbeitung ist, was ich kann und wenn Ihr bereit seid, Eure Gedanken den größeren Mächten der Substanz zu öffnen, werde ich mit Euch alles teilen, was es zu lernen gibt.\n\nDoch wisset dies, {class}: Durch die Wahl dieses Weges erklärt Ihr Euch einverstanden, niemals die Kunst der Drachenlederverarbeitung oder der Stammeslederverarbeitung zu erlernen. Ihr könnt nur eine dieser drei Künste erlernen. Des Weiteren benötige ich einen angemessenen Beweis, dass Ihr im Einklang mit den Elementen der Natur steht. Bringt mir dafür die reinsten Essenzen von Feuer, Wasser, Erde und Wind.", sourceObjective = "Bringt 2 Herzen des Feuers, 2 Kugeln des Wassers, 2 Erdenkerne und 2 Odem des Windes zu Sarah Gerber in die Sengende Schlucht.\n\nWenn Ihr diese Aufgabe abschließt, werdet Ihr Zugang zur Kunst der Elementarlederverarbeitung erhalten.\n\nWenn Ihr diese Aufgabe abschließt, werdet Ihr allerdings weder Drachenlederverarbeitung noch Stammeslederverarbeitung erlernen können; seid also vorher sicher, dass dies der Weg ist, dem Ihr folgen wollt.", sourceObjectiveStatus = "unverified-source-field" }
quests[5145] = { id = 5145, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drachenlederverarbeitung", description = "Drachenlederverarbeitung ist nicht einfach, aber sie ist sehr einträglich. Ich werde Euch beibringen, wie man diese feine Panzerrüstung fertigt, aber nur, wenn Ihr bestimmten Bedingungen zustimmt.\n\nMit der Wahl dieses Weges erklärt Ihr Euch einverstanden, niemals die Kunst der Elementarlederverarbeitung oder der Stammeslederverarbeitung zu erlernen. An der Spitze des Handwerks ist nur Platz für eine der drei. Des Weiteren werde ich eine Probe Eurer besten Arbeit aus dem Bereich der Skorpidrüstung benötigen. Schließlich benötige ich noch einen Beweis für Eure Fähigkeit, die Hauptzutat des Handwerks zu erlangen: Schuppen der Drachkin.", sourceObjective = "Bringt 2 feste Skorpidbrustplatten, 2 feste Skorpidhandschuhe und 10 Drachenschuppen zu Thorkaf Drachenaug im Ödland.\n\nWenn Ihr diese Aufgabe abschließt, werdet Ihr Zugang zur Kunst der Drachenlederverarbeitung erhalten.\n\nIhr könnt dann allerdings weder Elementarlederverarbeitung noch Stammeslederverarbeitung erlernen; seid also vorher sicher, dass dies der Weg ist, dem Ihr folgen wollt.", sourceObjectiveStatus = "unverified-source-field" }
quests[5146] = { id = 5146, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elementarlederverarbeitung", description = "Elementarlederverarbeitung ist, was ich kann und wenn Ihr bereit seid, Eure Gedanken den größeren Mächten der Substanz zu öffnen, werde ich mit Euch alles teilen, was es zu lernen gibt.\n\nDoch wisset dies, {class}: Durch die Wahl dieses Weges erklärt Ihr Euch einverstanden, niemals die Kunst der Drachenlederverarbeitung oder der Stammeslederverarbeitung zu erlernen. Ihr könnt nur eine dieser drei Künste erlernen. Des Weiteren benötige ich einen angemessenen Beweis, dass Ihr im Einklang mit den Elementen der Natur steht. Bringt mir dafür die reinsten Essenzen von Feuer, Wasser, Erde und Wind.", sourceObjective = "Bringt 2 Herzen des Feuers, 2 Kugeln des Wassers, 2 Erdenkerne und 2 Odem des Windes zu Brumn Winterhuf in den Arathibergen.\n\nWenn Ihr diese Aufgabe abschließt, werdet Ihr Zugang zur Kunst der Elementarlederverarbeitung erhalten.\n\nWenn Ihr diese Aufgabe abschließt, werdet Ihr allerdings weder Drachenlederverarbeitung noch Stammeslederverarbeitung erlernen können; seid also vorher sicher, dass dies der Weg ist, dem Ihr folgen wollt.", sourceObjectiveStatus = "unverified-source-field" }
quests[5147] = { id = 5147, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanted - Arnak Grimtotem" }
quests[5148] = { id = 5148, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stammeslederverarbeitung", description = "Um die Kunst der Stammeslederverarbeitung zu erlernen, müsst Ihr verstehen, wie urzeitlich die Natur wirklich ist; ich weiß, dass Ihr bereits die Kunst der Herstellung von Wildlederrüstungen gemeistert habt und ich bin bereit, Eure Ausbildung abzuschließen.\n\nDoch wisset dies, {class}: Durch die Wahl dieses Weges erklärt Ihr Euch einverstanden, niemals die Kunst der Drachenlederverarbeitung oder der Elementarlederverarbeitung zu erlernen. Ihr könnt nur eine dieser drei Künste erlernen. Bringt mir des Weiteren die feinsten Proben Eurer Wildlederrüstungen. Von diesem Punkt aus werden wir dann beginnen, an Eurem Können zu arbeiten.", sourceObjective = "Bringt eine Wildlederweste und einen Wildlederhelm zu Se'Jib im Schlingendorntal.\n\nWenn Ihr diese Aufgabe abschließt, werdet Ihr Zugang zur Kunst der Stammeslederverarbeitung erhalten.\n\nWenn Ihr diese Aufgabe abschließt, werdet Ihr allerdings weder Drachenlederverarbeitung noch Elementarlederverarbeitung erlernen können; seid also vorher sicher, dass dies der Weg ist, dem Ihr folgen wollt.", sourceObjectiveStatus = "unverified-source-field" }
quests[5149] = { id = 5149, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pamelas Puppe", description = "Meine Tante Marlene hat gesagt, ich soll in unserem Haus bleiben, weil mein Vater in den Kampf ziehen muss. Mein Vater ist der mutigste Mann auf der ganzen Welt!\n\nAber ich bin schon so lange hier und er ist nicht gekommen, um mich abzuholen. Manchmal kommen böse Leute und flüstern mir etwas zu und ich will, dass mein Vater sie wegjagt, aber er ist nicht hier!\n\nUnd manchmal, wenn es dunkel wird, möchte ich mit meiner Puppe spielen, aber das kann ich nicht, weil ich sie in der Stadt gelassen habe.\n\nKönnt Ihr vielleicht meine Puppe für mich suchen?", sourceObjective = "Sucht Pamelas Puppe.", sourceObjectiveStatus = "unverified-source-field" }
quests[5150] = { id = 5150, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dadanga ist hungrig!" }
quests[5151] = { id = 5151, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hyperkondensator-Dingsda", description = "Ich bin der einzige Überlebende des Angriffs der Zentauren auf unsere Karawane! Ein rarer, aber mächtiger Panther bewacht mein bestes Dingsda, das um seinen Hals geschlungen ist. Ha! Sogar die Zentauren erzittern in Anwesenheit dieser wilden Bestie!\n\nHier ist der Schlüssel zu dem Käfig. Sie haben alles dorthin gebracht, ihn aber in Ruhe gelassen. Erledigt diese Bestie, bringt meinen Hyperkondensator zurück und ich werde Euch belohnen.\n\nDie Überfallene Karawane befindet sich nördlich von hier.", sourceObjective = "Erschlagt die Bestie und bringt den Hyperkondensator sowie den Pantherkäfigschlüssel zu Wizlo Lagerputzer zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[5152] = { id = 5152, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tante Marlene", description = "Oh, ich bin ja so einsam. Wo ist meine Familie? Tante Marlene hat mir gesagt, ich soll hier bleiben, aber dann ist sie weggegangen und nicht wiedergekommen! Und mein Papa... habt Ihr ihn gesehen?\n\nVielleicht weiß Tante Marlene, wo er ist. Sie lebt in der Nähe von Andorhal, in einem Haus im Süden. Ich glaub, es war auf einem Hügel... sie sagt, es wäre auf einem Hügel.\n\nBitte, {name}. Wir sind doch jetzt Freunde! Könnt Ihr für mich mit meiner Tante sprechen?", sourceObjective = "Sprecht mit Marlene, südlich der Ruinen von Andorhal.", sourceObjectiveStatus = "unverified-source-field" }
quests[5153] = { id = 5153, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein seltsamer Historiker", description = "Ich wünschte, Joseph könnte wieder bei seiner Tochter sein, aber das geht nicht. Seine Seele wurde von der Geißel verdreht und er wurde zu einem Monster. Oh, er ist verloren!\n\nAber vielleicht können wir sein Schicksal ändern.\n\nDurchsucht die Gräber draußen nach Josephs Denkmal. Sein Körper ist nicht dort, da er vor Jahren zertrampelt und zerschmettert wurde, aber unter dem Denkmal liegt sein Ehering. Bringt den Ring zu Chromie...das ist eine merkwürdige Gnomin mit sehr merkwürdigen Kräften.\n\nChromie hält sich in dem zerstörten Gasthaus im nordwestlichen Teil von Andorhal auf.", sourceObjective = "Bringt Josephs Ehering zu Chromie.", sourceObjectiveStatus = "unverified-source-field" }
quests[5154] = { id = 5154, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Annalen von Darroheim", description = "Um Joseph Rotpfad zu retten, müssen wir zuerst seine Vergangenheit enthüllen. Wir können sie den 'Annalen von Darroheim' entnehmen, einem Buch, das im Rathaus von Andorhal aufbewahrt wird.\n\nBringt mir dieses Buch. Wir können etwas über Josephs Schicksal erfahren...und es mit etwas Glück...ändern!", sourceObjective = "Bringt die 'Annalen von Darroheim' zu Chromie in Andorhal.", sourceObjectiveStatus = "unverified-source-field" }
quests[5155] = { id = 5155, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Streitmacht von Jaedenar", description = "Wenn ich Euch in dieser Angelegenheit vertrauen soll, müsst Ihr Euch zuerst als vertrauenswürdig erweisen.\n\nIch muss sicher sein, dass Ihr ein Feind des Schattenrates seid - seine Mitglieder sind für viele böse Taten nah und fern verantwortlich.\n\nReist tiefer in den Teufelswald hinein. Im Westen werdet Ihr einen Pfad sehen, der nach Jaedenar führt. Dort schmiedet der Rat Pläne zusammen mit der Brennenden Legion.\n\nBetretet die Tiefen eines der von ihnen bewohnten verderbten Grabhügel und macht sie nieder. Kehrt zu mir zurück, wenn Ihr dies erledigt habt. Dann weiß ich, dass Ihr uns wirklich helfen wollt.", sourceObjective = "Betretet Jaedenar und erschlagt 4 Hunde von Jaedenar, 4 Gardisten von Jaedenar, 6 Adepten von Jaedenar und 6 Kultisten von Jaedenar, bevor Ihr zu Greta Mooshuf im Teufelswald zurückkehrt.", sourceObjectiveStatus = "unverified-source-field" }
quests[5156] = { id = 5156, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Verderbnis überprüfen", description = "Im Norden, entlang der östlichen Straße im so genannten Narbengrund, liegt ein Bereich, wo im letzten großen Krieg Höllenbestien herbeigerufen wurden; die Krater zernarben immer noch das Land, so wie die Höllenbestien selbst.\n\nIch möchte gern zwei Dinge wissen. Erstens, durchstreifen immer noch entropische Elementare das Gebiet? Und zweitens, sind die Krater immer noch mit dem verderbten, stinkenden Wasser gefüllt, das sich dort vor Jahren gesammelt hat? Würdet Ihr das für mich überprüfen, {name}? Seid aber vorsichtig, die Höllenbestien zerstören alles, was ihren Weg kreuzt.", sourceObjective = "Sucht und zerstört 2 entropische Bestien und 2 entropische Schrecken, während Ihr den Narbengrund erforscht. Nachdem Ihr überprüft habt, ob die Krater immer noch mit verderbtem Wasser gefüllt sind, kehrt zu Taronn Rotfeder im Teufelswald zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[5157] = { id = 5157, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verderbtes Wasser sammeln", description = "Tief in Jaedenar liegt die Schattenfeste - die Hauptfestung der Verderbnis und des Bösen.\n\nDer Schattenrat verfügt über Schutzzauber in Form von Kohlenpfannen, die seinen Unterschlupf umgeben. Wenn ich durch Wahrsagen noch weitere Informationen über unseren Feind herausfinden soll, müssen diese Kohlenpfannen gelöscht werden. Dann sollte ich den Rat ausspionieren und herausfinden können, wer ihn anführt.\n\nBitte, nehmt diese Feldflasche und füllt sie am Mondbrunnen im Zentrum von Jaedenar, wenn Euch dies möglich ist. Kommt dann zu mir zurück.", sourceObjective = "Bringt die leere Feldflasche zum Mondbrunnen im Zentrum von Jaedenar und füllt sie, bevor Ihr zu Greta Mooshuf im Teufelswald zurückkehrt.", sourceObjectiveStatus = "unverified-source-field" }
quests[5158] = { id = 5158, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spirituelle Hilfe suchen", description = "Bringt das verderbte Wasser ins Brachland, {name}. Südlich von Ratschet, versteckt entlang des Ufers, hält sich eine alte Freundin von mir auf, eine Schamanin namens Islen Wasserdeuter. Sie ist eine mächtige Schamanin, die uns helfen wird. Ihre Verbindung zu den Geistern des Wassers war immer stark. Dass unsere Aufgabe edel ist, sollte ausreichen, um sie und die Geister des Wassers dazu zu bringen, bei dieser Aufgabe zu helfen.\n\nIhr dürftet sie in einem kleinen Lager direkt am Wasser finden. Ach ja, {name}, ignoriert die Piraten...sie sind nur eine Plage und keine Bedrohung für Euch.", sourceObjective = "Bringt das verderbte Mondbrunnenwasser in das Brachland zu Islen Wasserdeuter.", sourceObjectiveStatus = "unverified-source-field" }
quests[5159] = { id = 5159, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesäubertes Wasser wird zum Teufelswald gebracht", description = "Dankt den Geistern, {name}. Sie sind diejenigen, die Euch zu Hilfe kamen, nicht ich.\n\nIch gebe Euch nun dieses geläuterte Wasser. Richtet Greta bitte meine Grüße und meine besten Wünsche aus. Sie kämpft mit etwas viel Größerem als die meisten von uns... wie sie sicherlich bald herausfinden wird.\n\nDer Schattenrat ist keine Kraft, die man unterschätzen sollte, {name}. Vergesst das nicht.\n\nGeht jetzt. Nehmt das Wasser und kehrt zu Greta zurück.", sourceObjective = "Bringt das geläuterte Mondbrunnenwasser zu Greta Mooshuf im Teufelswald.", sourceObjectiveStatus = "unverified-source-field" }
quests[5160] = { id = 5160, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die oberste Beschützerin", description = "Reist nach Kalimdor, {race}. Unser Schwarm ist in der frostigen Landschaft von Winterquell zu Hause. Wenn Ihr Winterquell erreicht habt, sucht die Höhlen von Mazthoril.\n\nAuf den eisigen Böden von Mazthoril werdet ihr Kobaltrunen finden. Haltet eine meiner Schuppen in der Hand und stellt Euch auf eine Rune. Ihr werdet dann zu Haleh transportiert, unserer obersten Beschützerin.\n\nGebt ihr die Schuppe, damit sie weissagen kann, was ich hier an diesem verlorenen Ort gesehen und gefühlt habe.", sourceObjective = "Begebt Euch nach Winterquell und sucht Haleh. Gebt ihr Awbees Schuppe.", sourceObjectiveStatus = "unverified-source-field" }
quests[5161] = { id = 5161, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Zorn des blauen Drachenschwarms", description = "Wir verstehen, was die verfluchte Brut von Todesschwinge zu tun versucht, und wir wissen, dass das unterbunden werden muss.\n\nDurch den Schutz, den der Schwarzfels Nefarian bietet, wird es für uns immer schwieriger zu intervenieren.\n\nWir können aber Euch, sterbliches Wesen, ermächtigen - solltet Ihr Euch dafür entscheiden.\n\nDer Weg, der vor Euch liegt, ist voller Gefahren. Ihr müsst Euch entscheiden, ob Ihr unsere Hilfe annehmt. Denkt darüber nach und sprecht erneut mit mir, wenn Ihr eine Entscheidung getroffen habt.", sourceObjective = "Sprecht mit Haleh, wenn Ihr weitermachen wollt.", sourceObjectiveStatus = "unverified-source-field" }
quests[5162] = { id = 5162, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Zorn des blauen Drachenschwarms", description = "Das Arkane kontrolliere ich und das Arkane wird Euch zu Eurem nächsten Ziel senden.\n\nWenn Ihr bereit seid, wird die Reise beginnen. Ihr werdet Euch zu den Pestländern begeben und mit Jeziba sprechen.\n\nEr ist ein Sterblicher, so weise wie die Uralten und so geduldig wie die unbewegliche Erde. Sucht ihn in Andorhal.", sourceObjective = "Sprecht mit Jeziba in den Pestländern. Er wohnt in Andorhal.", sourceObjectiveStatus = "unverified-source-field" }
quests[5163] = { id = 5163, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sind wir endlich da, Yeti?", description = "Es ist alles bereit, {name}!\n\nAlso, ich habe meinen Freunden bereits eine Nachricht geschickt und ihnen gesagt, dass ich eine Überraschung für sie habe. Und hier kommt Ihr ins Spiel!\n\nIch werde Euch meinen mechanischen Yeti geben und Ihr müsst sie überraschen, indem Ihr jeden meiner Freunde aufsucht, den Yeti einschaltet und zu ihnen schickt.\n\nNachdem Ihr ihn Legacki in der Ewigen Warte, Sprinkel in Gadgetzan und Quixxil in Marschalls Zuflucht gezeigt habt, kehrt zurück und berichtet mir, was geschehen ist!\n\nBitte bringt mir meinen Yeti dann wieder zurück.", sourceObjective = "Nehmt Umis mechanischen Yeti und erschreckt ihre Freunde damit:\n\nLegacki in der Ewigen Warte (Winterquell)\nSprinkel in Gadgetzan (Tanaris)\nQuixxil in Marschalls Zuflucht (Krater von Un'Goro)\n\nWenn Ihr damit fertig seid, bringt den mechanischen Yeti zu Umi zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[5164] = { id = 5164, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verzeichnis der Abtrünnigen", description = "Haleh hätte kein feineres Instrument der Gerechtigkeit wählen können. Lest das 'Verzeichnis der Abtrünnigen' und werdet erleuchtet.\n\nFalls Ihr durchhaltet... falls Ihr tut, was von Euch verlangt wurde... falls Ihr überlebt... werdet Ihr ein Held sein.", sourceObjective = "Lest das 'Verzeichnis der Abtrünnigen'.", sourceObjectiveStatus = "unverified-source-field" }
quests[5165] = { id = 5165, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Übergießen der Flammen des Schutzes", description = "Jetzt müsst Ihr nach Jaedenar zurückkehren. Die Kohlenpfannen sind wahrscheinlich über die ganze Schattenfeste verteilt. Übergießt jede ihrer Flammen, und der Schutz, den der Rat eingerichtet hat, wird zumindest für eine kurze Zeit erlöschen. Ich werde warten, dass dies geschieht. Wenn es so weit ist, werde ich einen tiefen Blick in die Feste werfen und versuchen herauszufinden, wer der Kopf dieser Bestie ist. Dann, und nur dann, werden wir sehen, ob wir sie direkt angreifen.", sourceObjective = "Übergießt die Flammen der vier Kohlenpfannen des Schutzes in der Schattenfeste im Teufelswald mit dem geläuterten Mondbrunnenwasser und kehrt danach zu Greta Mooshuf im Smaragdrefugium zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[5166] = { id = 5166, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brustplatte des chromatischen Drachenschwarms", description = "Das Schmieden einer mächtigen Brustplatte zum Schutz gegen die unerbittlichen Angriffe des chromatischen Drachenschwarms ist eigentlich recht ironisch.\n\nDie Schuppen der Bestien, die wir bekämpfen, müssen an einen makellosen Knochenpanzer eines alten chromatischen Drachen oder Großdrachen genäht werden. Derzeit ist nicht bekannt, ob es überhaupt welche gibt, und wir sollten hoffen, dass es niemals welche geben wird.\n\nUnd dann ist da noch die vielleicht schwierigste aller Komponenten: das Blut von Helden.\n\nDer Bildhauer muss diese Kreation dann schmieden.", sourceObjective = "Um die Brustplatte des chromatischen Drachenschwarms zu schmieden, müsst Ihr die folgenden Gegenstände zu Jeziba dem 'Bildhauer' bringen:\n\n1 chromatischen Knochenpanzer.\n\n10 glänzende chromatische Schuppen.\n\n10 Einheiten Blut von Helden.\n\n10 ausgefranste Monstrositätenstickereien.", sourceObjectiveStatus = "unverified-source-field" }
quests[5167] = { id = 5167, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beinplatten des chromatischen Widersetzers", description = "Der Knochenpanzer eines erwachsenen chromatischen Drachen wird benötigt, um die Grundlage der Gamaschen zu fertigen. Glänzende chromatische Schuppen werden dann auf das Grundgerüst aufgebracht und im Blut der Helden verzaubert. Schließlich muss noch die geschmeidige Haut des Schattens auf die inneren Schienbeinschützer aufgebracht werden.", sourceObjective = "Um die Beinplatten des chromatischen Widersetzers zu schmieden, müsst Ihr die folgenden Gegenstände zu Jeziba dem 'Bildhauer' bringen:\n\n1 chromatischer Knochenpanzer.\n\n10 glänzende chromatische Schuppen.\n\n10 Einheiten Blut von Helden.\n\n5 Häute des Schattens.", sourceObjectiveStatus = "unverified-source-field" }
quests[5168] = { id = 5168, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Helden von Darroheim", description = "Die Helden von Darroheim haben einen Platz in meinem Herzen und das Buch, das Ihr mir gebracht habt, die 'Annalen von Darroheim', erzählt ihre Geschichten.\n\nEs berichtet von dem Paladin Davil Lichterschein und davon, wie der Kreuzzug seinen Buchband zum Rathaus von Herdweiler brachte.\n\nEinige Passagen handeln auch von meinem Bruder, Hauptmann Rotpfad. Nach seinem Verrat wurde sein Schild zerschmettert und weggeworfen und liegt nun am unwahrscheinlichsten aller Orte - in der Nähe von Gahrrons Trauerfeld.\n\nSammelt diese Relikte, {name}. Denn Verhängnis und Tragik umgeben sie.", sourceObjective = "Bringt Davils Buchband und Rotpfads Schild zu Carlin Rotpfad.", sourceObjectiveStatus = "unverified-source-field" }
quests[5181] = { id = 5181, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bösewichte von Darroheim", description = "Die 'Annalen von Darroheim' berichten von den Bösewichten dieser Schlacht. Sie berichten, wie der Ghulfürst Horgus der Verheerer von Kräften der Allianz während der Schlacht vernichtet wurde. Seine Leiche wurde in einen See geworfen, nordwestlich von Corins Kreuzung, und sein Schädel ist noch dort.\n\nMarduk der Schwarze wurde nie besiegt, aber sein sagenhaftes Schwert wurde zertrümmert und ging verloren. Es liegt auf dem Grund der Schlucht westlich von Corins Kreuzung.\n\nBringt diese Gegenstände zurück, {name}. Ich weiß nicht, warum, aber ich bin sicher, dass ihr Schicksal in Euren Händen liegt.", sourceObjective = "Bringt den Schädel von Horgus und das zertrümmerte Schwert von Marduk zu Carlin Rotpfad in der Kapelle des Hoffnungsvollen Lichts.", sourceObjectiveStatus = "unverified-source-field" }
quests[5201] = { id = 5201, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eindringlinge der Winterfelle", description = "Meine Anwesenheit bleibt den Meisten verborgen, {name}. Es gibt aber eine Störung, die hier in Winterquell fest verankert zu sein scheint: die Winterfellfurbolgs.\n\nObwohl ich die Furbolgs nie direkt angegriffen habe, scheinen sie wahnsinnig zu sein, alles, was in ihrem Weg steht, scheint sie zu ängstigen. Ich habe beobachtet, wie sie zahllose Kreaturen erschlagen haben, die das Pech hatten, einfach zur falschen Zeit am falschen Ort zu sein.\n\nIch bin ihrer Einmischungen müde... helft mir bitte, indem Ihr sie bekämpft. Erschlagt die Furbolgs und haltet sie vom Frostsäblerfelsen fern.", sourceObjective = "Rivern Frostwind möchte, dass Ihr 5 Schamanen der Winterfelle und 5 Ursa der Winterfelle erschlagt.", sourceObjectiveStatus = "unverified-source-field" }
quests[5202] = { id = 5202, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein merkwürdiger roter Schlüssel", description = "Der kleine rote Schlüssel scheint aus einem Knochenmaterial gemacht zu sein. Er liegt schwer in Eurer Hand, wirkt aber trotzdem sehr zerbrechlich. Warum sollte ein Mitglied des Schattenrats solch ein Ding haben? Vielleicht gibt es etwas in Jaedenar, was dieser merkwürdige Schlüssel aufschließen kann.", sourceObjective = "Durchsucht Jaedenar, um herauszufinden, wofür der blutrote Schlüssel verwendet wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[5203] = { id = 5203, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rettung aus Jaedenar", description = "Aber so sehr es mich auch schmerzt, es gibt eine Sache, die zuerst erledigt werden muss. Ich muss Treys Schwert Lichtschmied finden und aus der Schattenfeste entkommen, um meinen Vorgesetzten zu berichten, was hier geschieht. Könntet Ihr mir helfen, {name}?\n\nUnsere Ausrüstung ist nicht weit von hier und Ihr habt bereits bewiesen, dass Ihr den Weg an die Spitze überleben könnt.\n\nNachdem wir entkommen sind, werde ich nach Darnassus gehen, und Euch würde ich bitten, meine Freundin Jessir in der Nähe der Grenze zum Eschental aufzusuchen. Sie sollte sich eigentlich im Lager des Smaragdkreises hier in der Nähe mit uns treffen.\n\nWas sagt Ihr dazu, {name}? Würdet Ihr mir nochmals helfen?", sourceObjective = "Bringt Arko'narin dorthin, wo Lichtschmied und ihre Ausrüstung aufbewahrt werden, und beschützt sie dann bei eurer Flucht aus der Schattenfeste. Sucht danach Jessir Mondsichel im Teufelswald auf und lasst sie wissen, was mit ihren Freunden geschehen ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[5204] = { id = 5204, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vergeltung des Lichts", description = "Sie möchte so tun, als ob es ihr gut ginge. Sie möchte gern, dass ich denke, sie sei stark genug, um mit alledem selbst fertigzuwerden, aber ich weiß es besser. Treys Tod und zu hören, welche Folter er erdulden musste, wird sie lange Zeit verfolgen und es gibt nichts, was wir tun können, um das zu stoppen. Aber wir können ihr ein wenig Frieden geben!\n\n{name}, kehrt zur Schattenfeste zurück, tötet Treys Folterer und sucht seine Überreste. Es gibt keinen Grund, dass wir nicht all diese Dinge zu Ende bringen können, während Arko'narin auf ihre eigene Art trauert.", sourceObjective = "Kehrt nach Jaedenar zurück und tötet den Sukkubus Rakaiah, bevor Ihr die Überreste von Trey Lichtschmied sucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[5206] = { id = 5206, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Marodeure von Darroheim", description = "Chromie sagte, dass die von Euch gesammelten Relikte Reagenzien für einen mächtigen Zauber seien und dass noch eines fehle: Schädel von Angehörigen der Geißel, die an der Schlacht von Darroheim teilnahmen.\n\nNehmt diesen Kristall und jagt um ihrer Schädel willen Champions der Geißel. Der Kristall ist verzaubert: Wenn ein Held an der Schlacht teilnahm, dann wird er, wenn Ihr ihn über dessen Schädel haltet, widerhallen. Bringt mir diese widerhallenden Schädel.\n\nGeht, {name}. Ihr könnt Champions der Geißel im Giftigen Tal im Norden und im Fungustal im Westen finden.", sourceObjective = "Bringt 5 widerhallende Schädel und den mystischen Kristall zu Carlin Rotpfad in den Östlichen Pestländern.", sourceObjectiveStatus = "unverified-source-field" }
quests[5210] = { id = 5210, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bruder Carlin", description = "Die 'Annalen von Darroheim' haben mithilfe meiner Magie an ihrem Ende Seiten hinzugewonnen, und nun erstreckt sich die Geschichte auch über den Kampf hinaus. Eine der zusätzlichen Passagen berichtet von einem anderen Rotpfad, Carlin, der Josephs Verrat überlebt hat. Carlin befindet sich jetzt in den Pestländern im Osten, bei der Kapelle des Hoffnungsvollen Lichts.\n\nNehmt das Buch und sprecht mit ihm.", sourceObjective = "Bringt die erweiterten 'Annalen von Darroheim' zu Carlin Rotpfad in den Östlichen Pestländern.", sourceObjectiveStatus = "unverified-source-field" }
quests[5211] = { id = 5211, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verteidiger von Darroheim", description = "Viele der Verteidiger fielen in der Schlacht von Darroheim. Und viele ziehen erneut umher als grässliche Diener der Geißel! Sucht diese armen Seelen und beendet ihr Elend!\n\nJagt Menschenfresserghule, jammernde Ghule und kranke Schinder. Viele dieser Scheusale waren einst gute Leute aus Darroheim und die Zerstörung ihrer Formen wird ihre Seelen befreien.\n\nIhr werdet sie im Pestwald und bei Corins Kreuzung finden, ebenso wie in anderen Geißelfestungen in den Östlichen Pestländern.", sourceObjective = "Befreit 15 Geister von Darroheim und kehrt dann zu Carlin Rotpfad zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[5212] = { id = 5212, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Fleisch lügt nicht", description = "Die Apotheker der Verlassenen sind nicht die einzigen Wesen auf dieser Welt, die in den Wissenschaften bewandert sind.\n\nIch erforsche die Seuche schon seit Jahren, {race}. Wir dachten zuerst, dass die Stärke der Seuche langsam schwand, aber was ich hier in den Pestländern entdeckt habe, ist alarmierend. Die Kraft der Seuche scheint zu wachsen!\n\nIch muss mehr Tests durchführen! Die mächtigste Quelle der Seuche ist das besudelte Fleisch der vor Kurzem Infizierten. Begebt Euch nach Stratholme und bringt mir Proben, {name}.", sourceObjective = "Sammelt 10 verseuchte Fleischproben in Stratholme und bringt sie zu Betina Moppelzink zurück. Ihr vermutet, dass Ihr besagte Fleischproben bei jeder Kreatur in Stratholme finden könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[5213] = { id = 5213, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der aktive Wirkstoff", description = "Ihr müsst tiefer nach Stratholme vordringen, {name}.\n\nHinter den ersten Toren werdet Ihr die Ziggurats finden. Wir wissen, dass die Geißel große Macht aus diesen Gebäuden zieht. Durchsucht die Ziggurats und kehrt mit den Informationen zurück, die Ihr aufspürt.", sourceObjective = "Reist nach Stratholme und durchsucht die Ziggurats. Sucht neue Geißeldaten und bringt sie zu Betina Moppelzink zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[5214] = { id = 5214, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Great Ezra Grimm" }
quests[5215] = { id = 5215, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Geißelkessel", description = "In den Ländern des ehemaligen Lordaeron befinden sich acht Kessel - vier hier im Westen und vier weitere versteckt im Osten. Diese Kessel speien Gifte in die Luft und verbreiten die Seuche für die Geißel im ganzen Land.\n\nDie nekromantische Macht von Kel'Thuzad ist zu stark, um diese Kessel gänzlich zu schließen, aber wir glauben zu wissen, wie wir sie zu unserem Vorteil nutzen könnten. Meine rechte Hand, die Hohepriesterin MacDonnell, wird Eure Kontaktperson für diesen Auftrag sein; sie wird die Einweisung fortsetzen.", sourceObjective = "Sprecht mit der Hohepriesterin MacDonnell an der Zugwindspitze in den Westlichen Pestländern.", sourceObjectiveStatus = "unverified-source-field" }
quests[5216] = { id = 5216, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ziel: Teufelssteinfeld", description = "Von den vier Kesseln, die sich hier im Westen befinden, ist derjenige, der sich auf dem Teufelssteinfeld befindet, wohl der, zu dem der Zugang am einfachsten ist. Die Geißel hat hier Truppen mit weniger Erfahrung positioniert, sie sollten aber trotzdem nicht unterschätzt werden.\n\nGeht zum Teufelssteinfeld, nordwestlich von Andorhal, und befasst Euch dort mit dem Kessellord. Wir glauben, dass er einen Schlüssel hat, der den Zugang zu dem Kessel freigeben wird. Wenn er frei ist, benutzt diese Flasche, um dem Kessel eine Probe des Giftes zu entnehmen; wir benötigen sie für die Entwicklung eines Gegenwirkstoffs.", sourceObjective = "Geht zum Teufelssteinfeld in den Westlichen Pestländern. Sucht nach dem dortigen Kessellord und besiegt ihn. Er könnte einen Schlüssel haben, der den Zugang zu dem Kessel ermöglicht. Ihr müsst die leere Flasche: Teufelssteinfeld bei Euch haben, um eine Probe des Giftes zu entnehmen, das sich in dem Kessel findet.", sourceObjectiveStatus = "unverified-source-field" }
quests[5217] = { id = 5217, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zum Zugwindlager", description = "Ihr füllt die Flasche mit einer ausreichenden Menge des giftigen Gebräus aus dem Kessel, sodass es für eine Probe zur Untersuchung reicht.\n\nMit dem Gift in der Hand ist es Zeit, zur Hohepriesterin MacDonnell an der Zugwindspitze zurückzukehren, um die Mission abzuschließen.", sourceObjective = "Bringt die gefüllte Flasche: Teufelssteinfeld zur Hohepriesterin MacDonnell an der Zugwindspitze in den Westlichen Pestländern.", sourceObjectiveStatus = "unverified-source-field" }
quests[5218] = { id = 5218, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Kessel des Teufelssteinfelds" }
quests[5219] = { id = 5219, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ziel: Dalsons Tränenfeld", description = "Einer der Seuchenkessel befindet sich auf dem Feld eines ehemaligen Bauernhauses, das jetzt Dalsons Tränenfeld genannt wird. Tja, wir werden heute keine Tränen vergießen, wenn wir der Geißel in die Quere kommen und sie an ihren eigenen Dämpfen ersticken lassen!\n\nBegebt Euch zu Dalsons Tränenfeld, ziemlich genau nördlich von Andorhal, und eliminiert den Kessellord dort. Er sollte, wie der Letzte auch, einen Schlüssel haben, durch den Ihr an den Kessel gelangen könnt. Benutzt diese Flasche, um eine Probe aus dem Kessel zu entnehmen; jeder Kessel enthält ein jeweils für ihn einzigartiges Gebräu aus Toxinen, das nur er benutzt.", sourceObjective = "Begebt Euch zu Dalsons Tränenfeld in den Westlichen Pestländern, um den dortigen Kessellord zu suchen und zu besiegen. Verwendet dann seinen Schlüssel, um Zugang zum Kessel zu erhalten. Ihr müsst die leere Flasche: Dalsons Tränenfeld bei Euch haben, um eine Probe des Giftes zu entnehmen, das sich in dem Kessel findet.", sourceObjectiveStatus = "unverified-source-field" }
quests[5220] = { id = 5220, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zum Zugwindlager", description = "Vorsichtig füllt Ihr so viel, wie Ihr für eine sinnvolle Probe für nötig erachtet, von dem Sekret aus dem Kessel in die Flasche.\n\nMit dem Gift in der Hand ist es Zeit, zur Hohepriesterin MacDonnell an der Zugwindspitze zurückzukehren, um die Mission abzuschließen.", sourceObjective = "Bringt die gefüllte Flasche: Dalsons Tränenfeld zur Hohepriesterin MacDonnell an der Zugwindspitze in den Westlichen Pestländern.", sourceObjectiveStatus = "unverified-source-field" }
quests[5221] = { id = 5221, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Kessel von Dalsons Tränenfeld" }
quests[5222] = { id = 5222, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ziel: Das Trostlose Feld", description = "Zwei Kessel wurden erfolgreich geöffnet. Auf diese könnt Ihr jetzt zwar unbegrenzt zugreifen, aber wir möchten immer noch, dass Ihr die beiden verbleibenden öffnet. Damit erhielten wir weitere Möglichkeiten, den Gegenwirkstoff einzusetzen!\n\nDieses Mal werdet Ihr Euch um den Kessel des Trostlosen Felds kümmern. Er befindet sich ziemlich genau östlich von Andorhal, relativ nahe bei den zerstörten Stadtmauern. Eliminiert auch dort den Kessellord, um an den Schlüssel zu gelangen. Benutzt diese Flasche, um eine Probe aus dem Kessel zu entnehmen.\n\nGute Jagd, {name}!", sourceObjective = "Begebt Euch zum Trostlosen Feld in den Westlichen Pestländern, um den dortigen Kessellord zu suchen und zu besiegen. Verwendet dann seinen Schlüssel, um Zugang zum Kessel zu erhalten. Ihr müsst die leere Flasche: Das Trostlose Feld bei Euch haben, um eine Probe des Giftes zu entnehmen, das sich in dem Kessel findet.", sourceObjectiveStatus = "unverified-source-field" }
quests[5223] = { id = 5223, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zum Zugwindlager", description = "Vorsichtig füllt Ihr die leere Flasche. Jetzt schwappt eine Probe der stinkenden Substanz, die unter der Plattform des Kessels brodelt, in dem zerbrechlichen Glasbehälter herum.\n\nMit dem Gift in der Hand ist es Zeit, zur Hohepriesterin MacDonnell an der Zugwindspitze zurückzukehren, um die Mission abzuschließen.", sourceObjective = "Bringt die gefüllte Flasche: Das Trostlose Feld zur Hohepriesterin MacDonnell an der Zugwindspitze in den Westlichen Pestländern.", sourceObjectiveStatus = "unverified-source-field" }
quests[5224] = { id = 5224, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Kessel des Trostlosen Felds" }
quests[5225] = { id = 5225, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ziel: Gahrrons Trauerfeld", description = "Der letzte verbleibende Kessel befindet sich auf einem Hof, der jetzt Gahrrons Trauerfeld genannt wird. Er wird durch einige der stärkeren Diener der Geißel bewacht... um genau zu sein durch Gespenster und Geisterscheinungen. Die darf man nicht unterschätzen, {name}.\n\nGahrrons Trauerfeld liegt von unserer Position hier aus im Nordosten, etwa dort, wo die Östlichen Pestländer beginnen. Eliminiert auch dort den Kessellord, um an den Schlüssel zu gelangen. Hier ist Eure leere Probenflasche; bringt sie mir gefüllt zurück. Möge das Licht Euch bei dieser gefährlichen Mission schützen, {class}.", sourceObjective = "Begebt Euch zu Gahrrons Trauerfeld in den Westlichen Pestländern, um den dortigen Kessellord zu suchen und zu besiegen. Verwendet dann seinen Schlüssel, um Zugang zum Kessel zu erhalten. Ihr müsst die leere Flasche: Gahrrons Trauerfeld bei Euch haben, um eine Probe des Giftes zu entnehmen, das sich in dem Kessel findet.", sourceObjectiveStatus = "unverified-source-field" }
quests[5226] = { id = 5226, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zum Zugwindlager", description = "Ihr schließt sorgfältig den Hahn in der Zugangsklappe und beobachtet, wie das faulige Sekret des Kessels in die leere Flasche tropft.\n\nMit dem Gift in der Hand ist es Zeit, zur Hohepriesterin MacDonnell an der Zugwindspitze zurückzukehren, um die Mission abzuschließen.", sourceObjective = "Bringt die gefüllte Flasche: Gahrrons Trauerfeld zur Hohepriesterin MacDonnell an der Zugwindspitze in den Westlichen Pestländern.", sourceObjectiveStatus = "unverified-source-field" }
quests[5227] = { id = 5227, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Kessel von Gahrrons Trauerfeld" }
quests[5228] = { id = 5228, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Geißelkessel", description = "In den Ländern des ehemaligen Lordaeron befinden sich acht Kessel - vier im Westen und vier weitere verschanzt im Osten. Diese Kessel speien Gifte in die Luft und verbreiten die Seuche für die Geißel im ganzen Land.\n\nDie nekromantische Macht von Kel'Thuzad ist zu stark, um diese Kessel gänzlich zu schließen, aber wir glauben zu wissen, wie wir sie zu unserem Vorteil nutzen könnten. Meine rechte Hand, die Schattenpriesterin Vandis wird Eure Kontaktperson für diesen Auftrag sein; sie wird die Einweisung fortsetzen.", sourceObjective = "Sprecht mit der Schattenpriesterin Vandis am Bollwerk in den Westlichen Pestländern.", sourceObjectiveStatus = "unverified-source-field" }
quests[5229] = { id = 5229, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ziel: Teufelssteinfeld", description = "Von den vier Kesseln, die sich in den Westlichen Pestländern befinden, ist derjenige, der sich im Teufelssteinfeld befindet, wohl der, zu dem der Zugang am einfachsten ist. Die Geißel hat hier Truppen mit weniger Erfahrung positioniert, sie sollten aber trotzdem nicht unterschätzt werden.\n\nGeht zum Teufelssteinfeld, direkt östlich von hier und nordwestlich von Andorhal, und befasst Euch dort mit dem Kessellord. Er hat einen Schlüssel bei sich, der den Zugang zu dem Kessel freigeben wird. Wenn er frei ist, benutzt diese Flasche, um dem Kessel eine Probe des Giftes zu entnehmen; wir benötigen sie für die Entwicklung eines Gegenwirkstoffs.", sourceObjective = "Geht zum Teufelssteinfeld in den Westlichen Pestländern. Sucht nach dem dortigen Kessellord und besiegt ihn. Er könnte einen Schlüssel haben, der den Zugang zu dem Kessel ermöglicht. Ihr müsst die leere Flasche: Teufelssteinfeld bei Euch haben, um eine Probe des Giftes zu entnehmen, das sich in dem Kessel findet.", sourceObjectiveStatus = "unverified-source-field" }
quests[5230] = { id = 5230, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zum Bollwerk", description = "Ihr füllt die Flasche mit einer ausreichenden Menge des giftigen Gebräus aus dem Kessel, sodass es für eine Probe zur Untersuchung reicht.\n\nMit dem Gift in der Hand ist es Zeit, zur Schattenpriesterin Vandis am Bollwerk zurückzukehren, um die Mission abzuschließen.", sourceObjective = "Bringt die gefüllte Flasche: Teufelssteinfeld zur Schattenpriesterin Vandis am Bollwerk in den Westlichen Pestländern.", sourceObjectiveStatus = "unverified-source-field" }
quests[5231] = { id = 5231, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ziel: Dalsons Tränenfeld", description = "Einer der Seuchenkessel befindet sich auf dem Feld eines ehemaligen Bauernhauses, das jetzt Dalsons Tränenfeld genannt wird. Heute werden keine Tränen vergossen, {class}; wir müssen bei diesem Kessel zuschlagen und Zugang zu ihm erlangen!\n\nBegebt Euch zu Dalsons Tränenfeld, fast direkt nördlich von Andorhal, und eliminiert den Kessellord dort. Er sollte, wie der Letzte auch, einen Schlüssel haben, durch den Ihr ans Innere des Kessels gelangen könnt. Benutzt diese Flasche, um eine Probe aus dem Kessel zu entnehmen; jeder Kessel enthält ein jeweils für ihn einzigartiges Gebräu aus Toxinen, das nur er benutzt.", sourceObjective = "Begebt Euch zu Dalsons Tränenfeld in den Westlichen Pestländern, um den dortigen Kessellord zu suchen und zu besiegen. Verwendet dann seinen Schlüssel, um Zugang zum Kessel zu erhalten. Ihr müsst die leere Flasche: Dalsons Tränenfeld bei Euch haben, um eine Probe des Giftes zu entnehmen, das sich in dem Kessel findet.", sourceObjectiveStatus = "unverified-source-field" }
quests[5232] = { id = 5232, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zum Bollwerk", description = "Vorsichtig füllt Ihr so viel, wie Ihr für eine sinnvolle Probe für nötig erachtet, von dem Sekret aus dem Kessel in die Flasche.\n\nMit dem Gift in der Hand ist es Zeit, zur Schattenpriesterin Vandis am Bollwerk zurückzukehren, um die Mission abzuschließen.", sourceObjective = "Bringt die gefüllte Flasche: Dalsons Tränenfeld zur Schattenpriesterin Vandis am Bollwerk in den Westlichen Pestländern.", sourceObjectiveStatus = "unverified-source-field" }
quests[5233] = { id = 5233, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ziel: Das Trostlose Feld", description = "Zwei Kessel wurden erfolgreich geöffnet. Auf diese könnt Ihr jetzt zwar unbegrenzt zugreifen, aber wir möchten immer noch, dass Ihr die beiden verbleibenden öffnet. Damit erhielten wir weitere Möglichkeiten, den Gegenwirkstoff einzusetzen!\n\nDieses Mal werdet Ihr Euch um den Kessel des Trostlosen Felds kümmern. Er befindet sich ziemlich genau östlich von Andorhal, relativ nahe bei den zerstörten Stadtmauern. Eliminiert auch dort den Kessellord, um an den Schlüssel zu gelangen. Benutzt diese Flasche, um eine Probe aus dem Kessel zu entnehmen.\n\nGute Jagd, {name}!", sourceObjective = "Begebt Euch zum Trostlosen Feld in den Westlichen Pestländern, um den dortigen Kessellord zu suchen und zu besiegen. Verwendet dann seinen Schlüssel, um Zugang zum Kessel zu erhalten. Ihr müsst die leere Flasche: Das Trostlose Feld bei Euch haben, um eine Probe des Giftes zu entnehmen, das sich in dem Kessel findet.", sourceObjectiveStatus = "unverified-source-field" }
quests[5234] = { id = 5234, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zum Bollwerk", description = "Vorsichtig füllt Ihr die leere Flasche. Jetzt schwappt eine Probe der stinkenden Substanz, die unter der Plattform des Kessels brodelt, in dem zerbrechlichen Glasbehälter herum.\n\nMit dem Gift in der Hand ist es Zeit, zur Schattenpriesterin Vandis am Bollwerk zurückzukehren, um die Mission abzuschließen.", sourceObjective = "Bringt die gefüllte Flasche: Das Trostlose Feld zur Schattenpriesterin Vandis am Bollwerk in den Westlichen Pestländern.", sourceObjectiveStatus = "unverified-source-field" }
quests[5235] = { id = 5235, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ziel: Gahrrons Trauerfeld", description = "Der letzte verbleibende Kessel befindet sich auf einem Hof, der jetzt Gahrrons Trauerfeld genannt wird. Er wird durch einige der stärkeren Diener der Geißel bewacht... um genau zu sein durch Gespenster und Geisterscheinungen. Die darf man nicht unterschätzen, {name}.\n\nGahrrons Trauerfeld liegt weit im Osten vom Bollwerk aus gesehen, etwa dort, wo die Östlichen Pestländer beginnen. Eliminiert auch dort den Kessellord, um an den Schlüssel zu gelangen. Hier ist Eure leere Probenflasche; bringt sie mir gefüllt zurück. Mögen die Schatten Euch für diese gefährliche Mission in Sicherheit hüllen, {class}.", sourceObjective = "Begebt Euch zu Gahrrons Trauerfeld in den Westlichen Pestländern, um den dortigen Kessellord zu suchen und zu besiegen. Verwendet dann seinen Schlüssel, um Zugang zum Kessel zu erhalten. Ihr müsst die leere Flasche: Gahrrons Trauerfeld bei Euch haben, um eine Probe des Giftes zu entnehmen, das sich in dem Kessel findet.", sourceObjectiveStatus = "unverified-source-field" }
quests[5236] = { id = 5236, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zum Bollwerk", description = "Ihr schließt sorgfältig den Hahn in der Zugangsklappe und beobachtet, wie das faulige Sekret des Kessels in die leere Flasche tropft.\n\nMit dem Gift in der Hand ist es Zeit, zur Schattenpriesterin Vandis am Bollwerk zurückzukehren, um die Mission abzuschließen.", sourceObjective = "Bringt die gefüllte Flasche: Gahrrons Trauerfeld zur Schattenpriesterin Vandis am Bollwerk in den Westlichen Pestländern.", sourceObjectiveStatus = "unverified-source-field" }
quests[5237] = { id = 5237, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission erfüllt!" }
quests[5238] = { id = 5238, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission erfüllt!" }
quests[5241] = { id = 5241, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Onkel Carlin", description = "Manchmal kann ich nachts meinen Onkel Carlin weinen hören. Es klingt, als ob er weit weg wäre, im Osten.\n\nIch hoffe, dass er nicht um mich weint! {name}, werdet Ihr meinen Onkel suchen und ihm sagen, dass es mir gut geht?\n\nWenn Ihr ihn findet, sagt ihm, dass ich auf ihn warte und die Geschichte hören möchte, die er immer erzählt hat... die über die Hasen und die Marmelade! Die Geschichte ist so lustig!", sourceObjective = "Sucht Carlin Rotpfad.", sourceObjectiveStatus = "unverified-source-field" }
quests[5242] = { id = 5242, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der endgültige Schlag", description = "Leider scheint die einzige Möglichkeit, diese Bedrohung für den Teufelswald zu stoppen, ein Frontalangriff zu sein. Es gibt keine anderen Wege in die Schattenfeste und ich habe keine Möglichkeit, Euch ins Innere zu teleportieren. Der gerade Weg hinab in die Tiefe ist der einzige Weg... und ich weiß auch, wen Ihr aufsuchen solltet. Sein Name ist Fel'dan...Schattenlord Fel'dan. Er ist der Sterbliche, der dort unten die Macht hat... er ist der Kopf der Schlange. Tötet ihn und seine beiden Sukkubus-Diener und kehrt zu mir zurück. Fel'dan ist derjenige, der Pakte mit der Legion schließt. Er muss aufgehalten werden.", sourceObjective = "Tötet Moora und Salia und bringt den Kopf von Schattenlord Fel'dan zu Greta Mooshuf im Teufelswald.", sourceObjectiveStatus = "unverified-source-field" }
quests[5243] = { id = 5243, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Häuser der Heiligen", description = "Ich sehe meinen Untod als eine Krankheit an, {race}. Eine Krankheit, die einfach nur eine Behandlung erfordert; sie ist aber auch ein großer Segen für die Argentumdämmerung. Wie kann man die Heiden der Geißel besser schlagen als durch den Untod?\n\nIch werde von meinen Kollegen wegen der Opfer, die ich dargebracht habe, geachtet, aber das Lob bedeutet mir nichts.\n\nWenn Ihr daran interessiert seid, der Argentumdämmerung zu helfen, kann ich Euch einen Auftrag anbieten.\n\nBegebt Euch nach Stratholme und holt unsere Reserven an heiligem Wasser. Durchsucht die Vorratskisten.", sourceObjective = "Begebt Euch nach Stratholme im Norden. Durchsucht die Vorratskisten, die über die Stadt verstreut sind, und holt 5 Einheiten Weihwasser von Stratholme. Kehrt zu Leonidas Bartholomäus dem Geachteten zurück, wenn Ihr genug der gesegneten Flüssigkeit gesammelt habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[5244] = { id = 5244, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Ruinen von Kel'Theril", description = "Die Geschichte hinter Kel'Theril ist die eines verfluchten Volkes, gebunden an den Ort, an dem es ein unglückliches Ritual versuchte...\n\nDie Hochgeborenen, die Ihr dort finden werdet, stahlen einst ein hochheiliges Artefakt in dem Glauben, dass sie seine Macht für sich selbst nutzen und so noch mächtiger werden könnten. Durch ihre Bemühungen zerbrach das Relikt in einer gewaltigen Explosion, bei der die Teile unter das Eis des Sees getrieben wurden...\n\nSprecht mit Jaron Steinschleifer, wenn Ihr mehr erfahren möchtet; er hat das Gebiet vor Kurzem besucht und kann Euch mehr berichten.", sourceObjective = "Sprecht mit Jaron Steinschleifer in Sternfall.", sourceObjectiveStatus = "unverified-source-field" }
quests[5245] = { id = 5245, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die gequälten Seelen von Kel'Theril", description = "Die Geister der Hochgeborenen sind erbärmliche Kreaturen, das ist mal sicher. Sie suchen immer noch nach Teilen dessen, was sie für immer nach Kel'Theril verdammte - das gestohlene Relikt.\n\nWenn Ihr so daran interessiert seid, nehmt meine Hacke und geht nach Süden zum See. Seht, ob Ihr die Teile des Relikts aus dem Eis holen könnt.\n\nWas Ihr da finden werdet, darüber kann ich Euch nichts sagen, aber ich kenne jemanden, der es vielleicht kann... Aurora Himmelsrufer; sie lebt beim Nordpassturm im nördlichen Teil der Östlichen Pestländer.", sourceObjective = "Benutzt Jarons Hacke, um die vier Fragmente des Hochgeborenenrelikts zu suchen. Bringt sie zu Aurora Himmelsrufer in den Östlichen Pestländern.", sourceObjectiveStatus = "unverified-source-field" }
quests[5246] = { id = 5246, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fragmente der Vergangenheit", description = "Ich wusste nicht, dass... Vergebt mir meine harten Worte, {class}.\n\nÜber die Fehler meiner Vorfahren möchte ich mich nicht auslassen, aber wenn Eure Bitte wirklich echt ist, dann werde ich Euch helfen.\n\n<Aurora untersucht die Fragmente.>\n\nIch glaube, dass dies der Kristall von Zin-Malor ist, ein Artefakt, das starke arkane Kräfte fesseln und kontrollieren kann. Es hätte für das Gute genutzt werden können, aber die bösen Absichten derjenigen, die es stahlen, ließen es zersplittern.\n\nBegebt Euch zum Tempel von Zin-Malor in Azshara - ich kann nur hoffen, dass das Buch noch dort ist.", sourceObjective = "Sucht die hochheiligen Schriften der Hochgeborenen im Tempel von Zin-Malor in Azshara und bringt sie zu Aurora Himmelsrufer beim Nordpassturm in den Östlichen Pestländern.", sourceObjectiveStatus = "unverified-source-field" }
quests[5247] = { id = 5247, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fragmente der Vergangenheit", description = "Ich kann Euch helfen, wenn Ihr das Artefakt wirklich wiederherstellen wollt.\n\nUm die Teile wieder zusammenzufügen und zu versiegeln, werde ich Gegenstände mit starken magischen Eigenschaften benötigen. Einen verzauberten Thoriumbarren und fünf Kristallflicker...Ihr werdet außerdem etwas Wasser von einem seltsam anmutenden Ort holen müssen...Sucht den Düsterteich entlang der Eldrethgasse in Düsterbruch in Feralas auf und füllt dort diese Phiole.\n\nWährend Ihr unterwegs seid, werde ich versuchen, diesen Seiten das Wissen zu entnehmen, das ich benötige, um den Schaden zu reparieren, der an dem Relikt verursacht wurde.", sourceObjective = "Bringt einen verzauberten Thoriumbarren, 5 Kristallflicker und eine Phiole mit Düsterwasser zu Aurora Himmelsrufer beim Nordpassturm in den Östlichen Pestländern.", sourceObjectiveStatus = "unverified-source-field" }
quests[5248] = { id = 5248, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gequält von der Vergangenheit", description = "{name}, ich weine ob dessen, was in der Vergangenheit geschehen ist. Wie dieser Kristall wurden auch die Elfen als Volk zerschmettert. Ich weiß nicht, ob die Teile jemals wieder zu einem vereinigt werden können, aber meine Trauer wurde dadurch gelindert, dass ich Euch bei dieser kleinen Aufgabe helfen konnte. \n\nWir dürfen die Vergangenheit nicht vergessen, {name}...\n\nBringt bitte den Kristall von Zin-Malor zurück zum Kel'Therilsee. Ihr müsst einen Geist eines Hochgeborenen finden, der erkennt, was für ein Fehler vor so langer Zeit begangen wurde. Zeigt dem Geist, dass wir die Dinge wieder in Ordnung gebracht haben.", sourceObjective = "Bringt den Kristall von Zin-Malor zum Kel'Therilsee in Winterquell und sucht einen Geist eines Hochgeborenen, der mit Euch sprechen will.", sourceObjectiveStatus = "unverified-source-field" }
quests[5249] = { id = 5249, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nach Winterquell!", description = "In Winterquell, nördlich von hier, gibt es viele alte Elfenruinen. Es ist ein raues Land, aber man kann dort viele Geheimnisse und Orte erkunden.\n\nBei der vielen Arbeit, die hier im Teufelswald meiner harrt, hatte ich keine Gelegenheit, nach Winterquell zu reisen. Aber es gibt keinen Grund, warum Ihr es nicht tun solltet!\n\nWährend Ihr dort seid, sucht doch nach Wynd Nachtjagd. Er verbringt den Großteil seiner Zeit in Sternfall und er weiß viel über die Gegend.", sourceObjective = "Sucht Sternfall in Winterquell und sprecht mit Wynd Nachtjagd.", sourceObjectiveStatus = "unverified-source-field" }
quests[5250] = { id = 5250, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sternfall", description = "In Winterquell, nördlich des Teufelswaldes, gibt es viele alte Elfenruinen. Es ist ein raues Land, aber man kann dort viele Geheimnisse und Orte erkunden.\n\nMeine Studien hier beschäftigen mich so sehr, dass ich seit einiger Zeit keine Gelegenheit mehr hatte, nach Winterquell zu reisen. Aber es gibt keinen Grund, warum Ihr nicht dorthin reisen und die Ruinen erforschen solltet.\n\nWährend Ihr dort seid, sucht doch nach Wynd Nachtjagd. Er verbringt den Großteil seiner Zeit in Sternfall und er weiß viel über die Gegend.\n\nSagt ihm, dass Ihr einer meiner Schüler seid...", sourceObjective = "Sucht die Siedlung Sternfall in Winterquell und sprecht mit Wynd Nachtjagd.", sourceObjectiveStatus = "unverified-source-field" }
quests[5251] = { id = 5251, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Archivar", description = "Alles, was zum Extremen getrieben wird, ist für unsere Welt gefährlich, {name}. Nehmt zum Beispiel den Scharlachroten Kreuzzug. Glaubt Ihr, dass der blinde Fanatismus seiner Anhänger etwas Gutem dient? Wie viele Unschuldige haben sie im Namen des Lichts vernichtet?\n\nGotteslästerer, alle zusammen!\n\nEiner interessiert mich aber besonders, der Archivar Galford von Stratholme: ein Mann, der über die wertvollsten Dokumente des Kreuzzugs wacht. Vernichtet ihn und verbrennt seine Archive! Wenn Ihr erfolgreich seid, kehrt zu mir zurück und Ihr werdet belohnt.", sourceObjective = "Reist nach Stratholme und sucht Archivar Galford vom Scharlachroten Kreuzzug. Vernichtet ihn und verbrennt das Scharlachrote Archiv.", sourceObjectiveStatus = "unverified-source-field" }
quests[5252] = { id = 5252, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reuevolle Hochgeborene", description = "Der... der Kristall...\n\nDie Hochgeborenen hier sssind durch ihr eigenessss Elend verwirrrrt...\n\nIch bin betrrrrübt, aber ich erkenne den Fehlerrr dessen, wassss vor so langer Zeit geschah. Obwohl esss keine Möglichkeit giiibt, die Vergangenheit zu ändern, habe ich nun Friiiieden gefunnnnden, da ich weiß, dass Ihr den Kristall von Zin-Malor wiederbeschafft habt...\n\nIiihr müsssssst ihn zurückbringennnn...\n\nEr muuussss zurückgebracht werrrdennnn.", sourceObjective = "Sprecht mit Wynd Nachtjagd in Sternfall und fragt nach dem richtigen Ort für den Kristall von Zin-Malor.", sourceObjectiveStatus = "unverified-source-field" }
quests[5253] = { id = 5253, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Kristall von Zin-Malor", description = "Recht eindrucksvoll, {name}.\n\nDer Kristall von Zin-Malor kann niemals in den Tempel zurückgebracht werden, der, wie Ihr wisst, nur noch eine Ruine ist. Aber ich finde, dass Eure Bemühung, das Böse der Vergangenheit ungeschehen zu machen, nicht ohne Belohnung bleiben soll.\n\nSucht den Erzdruiden Fandral Hirschhaupt in Darnassus auf und bringt ihm den Kristall, {name}. Er sollte sich in den Händen derer befinden, die seine Macht nicht missbrauchen werden. Wie es aussieht, sind von den stärksten Magieanwendern nur eine Handvoll in der Lage, solch eine Macht zu kontrollieren.", sourceObjective = "Überbringt dem Erzdruiden Fandral Hirschhaupt in Darnassus den Kristall von Zin-Malor.", sourceObjectiveStatus = "unverified-source-field" }
quests[5261] = { id = 5261, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eagan Pelzschneider", description = "Eagan Pelzschneider sucht nach jemandem, der für ihn erkrankte Wölfe jagt. Das ist gut, da wir hier im Nordhaintal in letzter Zeit sehr viele erkrankte Wölfe gesehen haben.\n\nWenn Ihr interessiert seid, dann sprecht mit Eagan. Ihr findet ihn neben der Abtei, auf der linken Seite.", sourceObjective = "Sprecht mit Eagan Pelzschneider.", sourceObjectiveStatus = "unverified-source-field" }
quests[5262] = { id = 5262, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Wahrheit zeigt sich mit Macht", description = "Ihr versucht, Eure Gedanken zu sammeln, während sich der Staub in der Kammer wieder setzt. Ihr geht in Gedanken die Ereignisse durch, die sich gerade ereignet haben, und könnt dennoch die Schwere der Situation nicht verstehen.\n\nDer Oberste Kreuzfahrer des Scharlachroten Kreuzzugs ein Dämon? Und nicht nur irgendein Dämon, sondern der Bruder von Varimathras, Erzlord von Unterstadt?\n\nIhr verstaut den abgetrennten Kopf des Schreckenslords sorgfältig in Eurem Rucksack. Natürlich würde Euch niemand diese Geschichte ohne Beweise glauben.\n\nFürst Nicholas Zverenhoff muss sofort davon erfahren!", sourceObjective = "Bringt den Kopf von Balnazzar zu Fürst Nicholas Zverenhoff in den Östlichen Pestländern.", sourceObjectiveStatus = "unverified-source-field" }
quests[5263] = { id = 5263, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Übertroffen", description = "Ihr zeigt eine natürliche Begabung für die Kunst der Zerstörung und Ihr folgt Befehlen. Es ist selten, dass beides zusammentrifft. In mir keimt immer mehr der Gedanke, dass Ihr ein hervorragendes Mittel göttlicher Gerechtigkeit darstellen könntet.\n\n<Zverenhoff verschränkt seine Hände vor seinem Gesicht.>\n\nDer Laufbursche von Kel'Thuzad regiert über Stratholme. Beweist mir, dass Ihr ein Held seid - mein Held. Vernichtet Baron Totenschwur und kehrt mit seinem Kopf zu mir zurück.", sourceObjective = "Zieht nach Stratholme und vernichtet Baron Totenschwur. Nehmt seinen Kopf und kehrt zu Fürst Nicholas Zverenhoff zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[5264] = { id = 5264, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lord Maxwell Tyrosus", description = "Ich werde Euch eine große Ehre zuteilwerden lassen, {name}.\n\nLord Maxwell wünscht, Euch für Euren Dienst an der Argentumdämmerung zu belohnen!\n\nEs ist Jahre her, seitdem Maxwell das letzte Mal einem Außenstehenden eine Audienz gewährt hat.", sourceObjective = "Sprecht mit Lord Maxwell Tyrosus. Er befindet sich in der Kirche.", sourceObjectiveStatus = "unverified-source-field" }
quests[5265] = { id = 5265, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Argentumtresor", description = "Über viele Jahre hinweg blieb der Argentumtresor verschlossen. Niemand war würdig genug, hineinzugreifen und die Macht der Argentumdämmerung herauszunehmen - bis heute.\n\nDer Argentumtresor ist nun für Euch geöffnet, {name}.", sourceObjective = "Öffnet den Argentumtresor und nehmt Euch Eure Belohnung.", sourceObjectiveStatus = "unverified-source-field" }
quests[5281] = { id = 5281, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die ruhelosen Seelen", description = "Da gibt es diejenigen, die tragisch beim Fall von Stratholme starben. Viele nahmen sich das Leben, entschieden sich dafür, sich lieber selbst in die Myriaden Flammen der glimmenden Stadt zu stürzen, statt einer der Geißel zu werden.\n\nNun ziehen sie als ruhelose Geister durch die Straßen von Stratholme.\n\nWir müssen ihnen helfen, {name}!\n\nIch habe einen Partner namens Egan, der wunderbare Arbeit mit Geistern und Seelen geleistet hat. Sucht ihn auf. Er streift durch die Östlichen Pestländer, in der Nähe von Stratholme, und testet seine Neuheiten.", sourceObjective = "Sucht Egan. Ihr wisst nur, dass er zuletzt in der Nähe von Stratholme gesehen wurde.", sourceObjectiveStatus = "unverified-source-field" }
quests[5282] = { id = 5282, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die ruhelosen Seelen", description = "Ich ziehe meine Macht - meinen Willen, weiter zu leben und zu atmen - aus dem ganzen Hass, den ich der Geißel entgegenbringe, und allem, was sie getan hat. Ich bin aber trotzdem kein Eiferer. Es gibt die, wie die Mitglieder des Scharlachroten Kreuzzugs, die die unschuldigen Untoten eher vernichten würden, als ihnen auch nur ein wenig Mitleid entgegenzubringen.\n\nDas bringt mich zu dem hier: meinem Blaster. Er wird die gequälten Seelen von Stratholme erlösen.\n\nWendet ihn auf die Geisterscheinungen an, die die geplünderten Straßen durchstreifen. Befreit ihre Seelen.", sourceObjective = "Wendet Egans Blaster auf die geisterhaften und spektralen Bürger von Stratholme an. Wenn die ruhelosen Geister ihre geisterhaften Hüllen sprengen, wendet den Blaster erneut an - dann sind sie endlich frei!\n\nBefreit 15 ruhelose Seelen und kehrt zu Egan zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[5283] = { id = 5283, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Kunst des Rüstungsschmiedes", description = "Tja, Ihr habt 'ne kluge Entscheidung getroffen.\n\nWir haben nix füreinander übrig, ich und der alte Ironus hier. Dieser nichtsnutzige Spielzeughersteller weiß, wer die wahren Handwerker hier sind.\n\nDie wirklich großen Kriege werden mit 'ner guten Verteidigung gewonnen. Wenn's losgeht, wird Euch kein Angriff helfen.\n\nAlso dann, ran an die Arbeit! Ihr müsst mir nur zeigen, dass Ihr über Talent verfügt. Danach reiß ich alle Unreinheiten, die noch in Euch sind, raus und mach einen Rüstungsschmied aus Euch. Ihr wisst doch, wie man verschnörkeltes Mithril herstellt, nicht wahr?", sourceObjective = "Um Rüstungsschmied zu werden, müsst Ihr die folgenden Gegenstände herstellen und zu Grumnus bringen: 4 verschnörkelte Mithrilhelme, 2 verschnörkelte Mithrilstiefel, 1 verschnörkelte Mithrilbrustplatte.", sourceObjectiveStatus = "unverified-source-field" }
quests[5284] = { id = 5284, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Weg des Waffenschmieds...", description = "Als Waffenschmied werdet Ihr feststellen, dass sehr häufig Helden und Abenteurer der Ausrüstung wegen zu Euch kommen werden. Wenn die viele Arbeit manchmal auch unerträglich sein kann, macht der Wohlstand aber doch die Rückenschmerzen und die Aschenlunge wett.\n\nOh ja, {name}, Waffenschmiede sind die mit dem ganzen Gold!\n\nWenn Ihr unseren Rängen beitreten wollt, müsst Ihr mir zeigen, dass Ihr mir ein Silberstück oder zwei machen könnt - ich meine, zeigt mir, dass Ihr habt, was man braucht, wenn Menschen Waffen überragender Qualität benötigen. An die Arbeit!", sourceObjective = "Um Waffenschmied zu werden, müsst Ihr die folgenden Gegenstände herstellen und zu Ironus bringen: 4 Mondstahlbreitschwerter, 4 massive Eisenäxte, 2 schwere Mithriläxte und 2 große schwarze Streitkolben.", sourceObjectiveStatus = "unverified-source-field" }
quests[5301] = { id = 5301, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Kunst des Rüstungsschmiedes", description = "Zufriedenheit. Das bekomme ich von Hammer und Amboss. Einen stolzen Krieger der Horde zu sehen, der von meinem Stahl geschützt ist, erinnert mich daran, was es heißt, am Leben zu sein. Das ist eine Sucht, die ich niemals ablegen werde, {name}.\n\nIch kann Euch diese Zufriedenheit nicht garantieren, Euch nur auf den Weg dazu bringen. Wie bei allen Bestrebungen des Lebens ist auch der Weg des Rüstungsschmieds eine Reise.\n\nWenn Ihr einer der wenigen Erwählten sein wollt, müsst Ihr nur fragen und ich werde Euch ausbilden, aber zuerst müsst Ihr eine Aufgabe erledigen.", sourceObjective = "Um Rüstungsschmied zu werden, müsst Ihr die folgenden Gegenstände herstellen und zu Okothos bringen: 4 verschnörkelte Mithrilhelme, 2 verschnörkelte Mithrilstiefel, 1 verschnörkelte Mithrilbrustplatte.", sourceObjectiveStatus = "unverified-source-field" }
quests[5302] = { id = 5302, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Weg des Waffenschmieds...", description = "Eines Tages werde ich einen legendären Hammer erschaffen. Einen Hammer, der eines Kriegshäuptlings würdig ist!\n\nDas ist mein Lebenswerk, {name}. Meine Leidenschaft. Ich erkenne, dass Ihr das Potenzial habt, zu uns zu gehören, einer von uns zu sein - ein Waffenschmied. Ich bin derjenige, der Euch helfen kann, dieses Potenzial nutzbar zu machen.\n\nAlles, was Ihr dafür erledigen müsst, ist eine einfache Aufgabe. Einfach für jemanden von Eurer außergewöhnlichen Fertigkeit.", sourceObjective = "Um Waffenschmied zu werden, müsst Ihr die folgenden Gegenstände herstellen und zu Borgosh bringen: 4 Mondstahlbreitschwerter, 4 massive Eisenäxte, 2 schwere Mithriläxte und 2 große schwarze Streitkolben.", sourceObjectiveStatus = "unverified-source-field" }
quests[5305] = { id = 5305, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Süße Beschaulichkeit", description = "In den Grenzen der Scharlachroten Bastion liegt die süße Beschaulichkeit. Der purpurrote Hammerschmied bewacht das Rezept mit seinem Leben. Besiegt ihn und bringt mir seine Schürze. Dafür werde ich Euch mit dem Wissen ausstatten, wie man einen verzauberten Kampfhammer herstellt!", sourceObjective = "Begebt Euch nach Stratholme und tötet den purpurroten Hammerschmied. Nehmt die Schürze des purpurroten Hammerschmiedes und kehrt zu Lilith zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[5306] = { id = 5306, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlangenstein der Schattenjägerin", description = "Lasst Euch von ihrer Schönheit nicht narren, {class}. Die Schattenjägerin Vosh'gajin ist todbringend und wahnsinnig.\n\n<Kilram zeigt auf die Narbe in seinem Gesicht.>\n\nJa, die habe ich von ihr - eine Liebkosung, wie sie es nannte.\n\nJetzt endlich ist die Zeit der Rache gekommen.\n\nIhr könnt Vosh'gajin in der Schwarzfelsspitze finden. Erschlagt sie und kehrt mit ihrem Schlangenstein zu mir zurück. Erledigt das und ich werde Euch das Geheimnis des Schmiedens der Dämmerungsschneide beibringen!", sourceObjective = "Begebt Euch zur Schwarzfelsspitze und erschlagt Schattenjägerin Vosh'gajin. Holt Vosh'gajins Schlangenstein und kehrt zu Kilram zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[5307] = { id = 5307, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verderbnis", description = "Wenn ich mit Euch kurz angebunden bin, dann gibt es einen Grund dafür. Die Pläne für die Erschaffung der großen Klinge, der Verderbnis, wurden von der schwarzen Wache gestohlen: den Skeletteliteeinheiten von Baron Totenschwur.\n\nJa, Baron Totenschwur von Stratholme.\n\nDer Schwertschmied der schwarzen Wache bewacht diese Pläne nun mit seinem...Untod.\n\nErschlagt ihn, kehrt mit einem Beweis für diese Tat zurück und ich werde Euch das Wissen schenken, mit dem Ihr einen Loderflammenrapier herstellen könnt.", sourceObjective = "Findet den Schwertschmied der schwarzen Wache in Stratholme und vernichtet ihn. Holt die Insignien der schwarzen Wache und kehrt zu Seril Geißelbann zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[5321] = { id = 5321, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schläfer ist erwacht", description = "Ich war auf dem Weg zu Maestras Posten, um mich mit Liladris Mondbach zu treffen, als ich beschloss, hier anzuhalten und ein kurzes Nickerchen zu machen. Seit ich aus dem Smaragdgrünen Traum aufgewacht bin, bin ich ständig so müde...\n\n<gähnt>\n\nKönntet Ihr mir den Weg zeigen? Ich weiß, dass Maestras Posten südlich von hier ist, entlang der Straße im Eschental. Es kann gefährlich werden, daher hoffe ich, dass Ihr einige Freunde habt, die sich uns anschließen werden.\n\nAußerdem könnte ich einschlafen. Wenn Ihr mich also einmal aufwecken müsst, dann benutzt dazu bitte mein Horn. Ihr findet es in der Truhe hier.", sourceObjective = "Begleitet Kerlonian Schattenspiel zu Liladris Mondbach in Maestras Posten im Eschental.", sourceObjectiveStatus = "unverified-source-field" }
quests[5341] = { id = 5341, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Familienvermögen der Barovs", description = "In Scholomance liegt das Familienvermögen der Barovs. Ich, Alexi Barov, bin einer der beiden letzten verbliebenen Erben des Hauses Barov. Mein Bruder Weldon ist der andere.\n\nWeldon, der jämmerliche Feigling, floh während des Krieges und hielt so an seiner wertlosen Existenz als Mensch fest.\n\nJetzt sucht er nach den Besitzurkunden, damit er das Vermögen für sich beanspruchen kann. Holt die Besitzurkunden, bevor mein Bruder es tut, und ich werde Euch reicher machen, als Ihr je zu träumen gewagt habt.", sourceObjective = "Begebt Euch zur Scholomance und holt das Familienvermögen der Barovs zurück. Dieses Vermögen besteht aus vier Besitzurkunden: Es sind die Besitzurkunde für Darrowehr, die Besitzurkunde für Brill, die Besitzurkunde für Tarrens Mühle und die Besitzurkunde für Süderstade. Kehrt zu Alexi Barov zurück, sobald die Aufgabe erledigt ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[5342] = { id = 5342, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der letzte Barov", description = "Da mein Bruder noch am Leben ist, wird es möglicherweise einen Disput darüber geben, wer der Hauptbegünstigte des Familienvermögens ist. Das darf nicht sein.\n\nEin niederer Gossenstreuner wie Ihr hat ja wohl nichts gegen einen kleinen kaltblütigen Mord einzuwenden, hoffe ich.\n\nEs ist eine einfache Aufgabe und ich erwarte, dass Ihr sie erfüllt... das heißt, falls Ihr Eure Belohnung erhalten wollt.\n\nWeldon sitzt unter dem Schutz der Allianz im Zugwindlager im Osten. Erschlagt ihn, bringt seinen Kopf zurück.\n\n<Alexi gähnt.>\n\nUnd jetzt fort mit Euch.", sourceObjective = "Begebt Euch zum Zugwindlager - Territorium der Allianz - und ermordet Weldon Barov. Nehmt seinen Kopf und kehrt zu Alexi Barov zurück.\n\nSeid gewarnt, Weldon wird wahrscheinlich gut von Abschaum der Allianz geschützt.", sourceObjectiveStatus = "unverified-source-field" }
quests[5343] = { id = 5343, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Familienvermögen der Barovs", description = "Mein lieber Bruder Alexi. Was für ein Narr war ich doch, sein Leben zu verschonen. Ich sah dem Feind ins Gesicht, einem der Untoten, und ließ ihn am Leben.\n\n<Weldon spuckt aus.>\n\nUnd jetzt sucht er nach MEINEM Erbe. Das darf einfach nicht sein.\n\nSucht die Besitzurkunden meiner Familie, bevor sie diesem niederträchtigen Bastard in seine knochigen Hände fallen, und ich werde Euch mit großem Reichtum belohnen. Sie liegen irgendwo in den Ruinen der Scholomance. Beeilt Euch!", sourceObjective = "Begebt Euch zur Scholomance und holt das Familienvermögen der Barovs zurück. Dieses Vermögen besteht aus vier Besitzurkunden: Es sind die Besitzurkunde für Darrowehr, die Besitzurkunde für Brill, die Besitzurkunde für Tarrens Mühle und die Besitzurkunde für Süderstade. Kehrt zu Weldon Barov zurück, sobald die Aufgabe erledigt ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[5344] = { id = 5344, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der letzte Barov", description = "Da die Besitzurkunden beschafft sind, bleibt nur noch eine Sache zu tun. Alexi muss getötet werden. Wenn er tot ist, brauche ich nicht mehr zu fürchten, dass eine skrupellose Bande von Söldnern meinen Kopf haben will.\n\nDie Aufgabe ist einfach. Alexi versteckt sich unter dem Schutz der Horde - beim Bollwerk.\n\nNein, ich erwarte nicht, dass Ihr einfach nur hingeht und ihn tötet, ich will seinen Kopf! Wie Ihr ihn bekommt...tja, dieser Part ist Euch überlassen. Ein derartiges Verhalten ist einem von meiner edlen Erziehung nicht würdig..", sourceObjective = "Begebt Euch zum Bollwerk - Territorium der Horde - und ermordet Alexi Barov. Nehmt seinen Kopf und kehrt zu Weldon Barov zurück.\n\nSeid gewarnt, Alexi wird wahrscheinlich gut durch Abschaum der Horde geschützt.", sourceObjectiveStatus = "unverified-source-field" }
quests[5361] = { id = 5361, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stammbaum", description = "Mein Bruder Nataka ist beim Geistwandlerposten drüben in Desolace stationiert. Also, worum ich Euch bitten möchte, ist... könntet Ihr ihm diesen Bericht von mir geben? Ein Jahr ist vergangen, seit ich ihm das letzte Mal schrieb, und es gab seitdem ungewöhnliche Zentaurenaktivitäten, über die er informiert werden sollte.\n\nReist zum Steinkrallengebirge nördlich des Wegekreuzes und dann westlich zum Verbrannten Tal. Begebt Euch von dort aus südlich nach Desolace; dort findet Ihr eine Straße, die gen Süden zum Geistwandlerposten führt.", sourceObjective = "Bringt den Bericht von Klippenbehüter Langhorn zu Nataka Langhorn am Geistwandlerposten in Desolace.", sourceObjectiveStatus = "unverified-source-field" }
quests[5381] = { id = 5381, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hand von Iruxos", description = "Die Brennende Klinge ist im Besitz des Dämonenkastens. Darin liegt die mächtige Hand von Iruxos. Die Anhänger der Brennenden Klinge verwenden sie, um dämonische Portale beim Zirkel der Mannoroc zu öffnen. Wir müssen die Flut der Dämonen stoppen, die in unsere Welt eindringt, {name}!\n\nWendet diese Dämonenhacke auf den roten Kristall in der Festung Donneraxt an, um Zugang zu dem Dämonenkasten zu erlangen.", sourceObjective = "Holt den Dämonenkasten aus der Festung Donneraxt und kehrt damit zu Taiga Klugmähne nach Schattenflucht zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[5382] = { id = 5382, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Doktor Theolen Krastinov, der Schlächter", description = "Krastinov ist für den Tod von Tausenden verantwortlich. Er muss bestraft werden, die Gerechtigkeit muss ihren Lauf nehmen.\n\nSucht ihn und bringt jene Qual über ihn, die er über zahllose Unschuldige gebracht hat. Wenn er vernichtet ist, verbrennt unsere Überreste. Verwandelt sie in Asche, {name}.", sourceObjective = "Sucht Doktor Theolen Krastinov in Scholomance. Vernichtet ihn, verbrennt dann die Überreste von Eva Sarkhoff und die Überreste von Lucien Sarkhoff. Kehrt zu Eva Sarkhoff zurück, sobald Ihr die Aufgabe erfüllt habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[5383] = { id = 5383, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krastinovs Tasche der Schrecken", description = "Ihr öffnet die Tasche und entdeckt darin verschiedene Folterinstrumente. Unter dem Zubehör fällt Euch ein merkwürdiges Objekt ins Auge. Eine Phiole mit Blut - noch immer warm.\n\nIhr denkt, dass die Sarkhoffs an Eurer Entdeckung interessiert sein könnten.", sourceObjective = "Bringt die Tasche der Schrecken zu Eva Sarkhoff in Darrowehr.\n\nBereitgestellter Gegenstand:", sourceObjectiveStatus = "unverified-source-field" }
quests[5384] = { id = 5384, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kirtonos der Herold", description = "Das ist es, {name}.\n\n<Eva zeigt auf die Phiole in der Tasche.>\n\nDas Blut von Unschuldigen. Das reinste Blut... damit wird Krastinovs Meister besänftigt.\n\nMit diesem Blut kann Kirtonos beschworen werden. Mit diesem Blut muss Kirtonos auch vernichtet werden.\n\nBringt dieses Blut auf die Veranda. Legt es auf die Kohlenpfanne. Kirtonos wird kommen - er kann nicht widerstehen. Wenn er erscheint, entfesselt die Wut und den Zorn von Tausenden unschuldigen Toten über ihm.\n\nWenn Ihr erfolgreich seid, werdet Ihr mehr verdienen als nur unsere Dankbarkeit.", sourceObjective = "Kehrt mit dem Blut Unschuldiger zur Scholomance zurück. Sucht die Veranda und legt das Blut der Unschuldigen in die Kohlenpfanne. Kirtonos wird kommen, um sich von Eurer Seele zu nähren.\n\nKämpft tapfer, gebt keinen Fußbreit nach! Vernichtet Kirtonos und kehrt zu Eva Sarkhoff zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[5385] = { id = 5385, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Überreste von Trey Lichtschmied", description = "Ihr hebt den Sack vorsichtig auf und macht Euch auf den Rückweg zu Jessir Mondsichel an der Grenze des Teufelswaldes und des Eschentals. Hoffentlich wird dem Paladin der ihm zustehende Respekt erwiesen, wenn Ihr seine Überreste seinen Freunden übergeben habt.", sourceObjective = "Bringt die Überreste von Trey Lichtschmied zu Jessir Mondsichel im Teufelswald.", sourceObjectiveStatus = "unverified-source-field" }
quests[5386] = { id = 5386, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Fang des Tages", description = "Der Geruch von gekochtem Fisch ist hier im Geistwandlerposten schon längst verschwunden. Die Trolle von Schattenflucht sind die Besten, wenn es um das Fangen von Fischen geht... aber leider habe ich aufgrund all der Zentaurenaktivitäten nicht genug Zeit, um eine Reise zu den Trollen zu unternehmen. Hm...\n\nTut mir einen Gefallen und reist nach Schattenflucht. Sprecht mit dem dortigen Angler Jinar'Zillen und bringt mir mein Leibgericht, Blutbauchfisch. Die Straße südlich von hier bringt Euch nach Westen zu dem Trolldorf.", sourceObjective = "Sprecht mit Jinar'Zillen in Schattenflucht und bringt Nataka Langhorn dann 2 Blutbauchfische.", sourceObjectiveStatus = "unverified-source-field" }
quests[5401] = { id = 5401, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anstecknadel der Argentumdämmerung" }
quests[5402] = { id = 5402, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geißelsteine des Dieners" }
quests[5403] = { id = 5403, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geißelsteine des Eindringlings" }
quests[5404] = { id = 5404, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geißelsteine des Verderbers" }
quests[5405] = { id = 5405, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anstecknadel der Argentumdämmerung" }
