quests[5408] = { id = 5408, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geißelsteine des Dieners" }
quests[5421] = { id = 5421, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fisch im Eimer", description = "Ich belohne jeden, der mein Leben 'n bisschen einfacher macht... ich mag's, mich so wenig wie möglich anzustrengen, Mann!\n\nUnterhalb des Stegs hier in Schattenflucht hab' ich 'ne Menge Schalentierfallen. Wenn du so nett wärst, mir die Arbeit abzunehmen und mir meine Schalentiere einsammelst, dann belohne ich dich mit etwas, das du brauchst... wenn du verstehst was ich meine, Mann?", sourceObjective = "Jinar'Zillen möchte, dass Ihr 5 Schalentiere aus den Fallen rund um Schattenflucht holt.", progress = "Haste meine Schalentiere, Mann?", completion = "Echt toll, nichts ist besser als getane Arbeit, vor allem, wenn sie jemand anderes getan hat... eh?", sourceObjectiveStatus = "unverified-source-field" }
quests[5441] = { id = 5441, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Faule Peons", description = "Verfluchte Peons! Sie arbeiten ja hart daran, Holz aus den Bäumen im Tal zu gewinnen, aber sie machen ständig Nickerchen! Ich brauche jemanden, der dabei hilft, die Peons auf Zack zu halten.\n\nIhr seht wie geschaffen für meinen Auftrag aus, {race}. Hier, Ihr nehmt jetzt diesen Totschläger und lasst ihn auf allen faulen Peons tanzen, die Ihr bei der Arbeit schlafend vorfindet. Ein ordentlicher Schlag wird sie schnell wieder an die Arbeit bringen! Bringt mir den Totschläger wieder, wenn Ihr fertig seid.\n\nVerdammte faule Peons...", sourceObjective = "Benutzt den Totschläger des Großknechts an faulen Peons, wenn sie schlafen. Weckt 5 Peons auf und bringt dann den Totschläger des Großknechts zu Großknecht Thazz'ril ins Tal der Prüfungen zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[5461] = { id = 5461, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Mensch Ras Frostraunen", description = "Die Untoten fürchten das Leben genauso sehr wie die Lebenden den Tod fürchten. Es ist nicht ungewöhnlich, dass ein denkender Untoter alle Überreste seines vorherigen Lebens vollständig zerstört, nachdem er zum Untoten wurde.\n\nLeider benötigen wir, um ein Artefakt zu erschaffen, das Ras Frostraunen wieder in einen Sterblichen zurückverwandeln kann, ein Andenken aus seinen Jahren unter den Lebenden.\n\nIhr müsst Euch zur zerstörten Stadt von Stromgarde begeben, Frostraunens Heim, und nach solch einem Gegenstand suchen. Möge das Glück mit Euch sein, {name}.", sourceObjective = "Reist in das Arathihochland zu den Ruinen von Stromgarde. Durchsucht Stromgarde nach einem Andenken der Erinnerung. Wenn Ihr einen solchen Gegenstand findet, kehrt mit ihm zu Magistrat Marduk zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[5462] = { id = 5462, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Sterbende Ras Frostraunen", description = "Das Andenken muss auf besudeltem Boden korrekt eingestellt werden.\n\nMan erzählt sich, dass Stratholme der Ort sei, an dem Frostraunen dem Lichkönig erlag. Auf diesem blutigen Boden gab er sein Leben – frei und mit einem Motiv –, um einer der Unsterbenden zu werden.\n\nDieser Ort muss gefunden werden.\n\nEs gibt einen untoten Dissidenten der Geißel, der durch die Bansheekönigin befreit wurde, aber der Sache der Argentumdämmerung gegenüber loyal ist. Sucht ihn: Leonidas Bartholomäus der Geachtete. Er könnte mehr wissen. Sucht die Kapelle des Hoffnungsvollen Lichts auf, {name}.", sourceObjective = "Reist zur Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern und sucht Leonidas Bartholomäus den Geachteten auf. Zeigt ihm das Andenken der Erinnerung und berichtet ihm alles, was Ihr entdeckt habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[5463] = { id = 5463, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Menethils Geschenk", description = "Ich sah zu, wie der Mensch Ras Frostraunen seine unsterbliche Seele dem Lichkönig verpfändete. Er setzte den Dolch an seiner eigenen Kehle an und durchschnitt sie mit einem Lächeln von einem Ohr zum anderen. Sein Körper brach in den Grenzen des Pentagramms zusammen. Der Lichkönig stand über dem gefallenen Magier, und mit einer einzigen Bewegung wurde Ras Frostraunen der Lich geboren.\n\n<Leonidas blickt zu Boden und sieht Euch dann an.>\n\nJa, {race}, ich erinnere mich. Was Ihr sucht, hat einen Namen - Menethils Geschenk: Der vom Lichkönig gesegnete Boden - heiliger Boden für die Geißel.", sourceObjective = "Begebt Euch nach Stratholme und sucht Menethils Geschenk. Platziert das Andenken der Erinnerung auf dem unheiligen Boden.", sourceObjectiveStatus = "unverified-source-field" }
quests[5464] = { id = 5464, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Menethils Geschenk", description = "Die Seele des Gefallenen hängt sich an das, was sein ehemaliges Leben repräsentiert, und verwandelt den Gegenstand in ein seelengebundenes Andenken. Ihr hebt den Gegenstand auf und verstaut ihn in Eurem Rucksack.", sourceObjective = "Bringt das seelengebundene Andenken zu Leonidas Bartholomäus in den Östlichen Pestländern.", sourceObjectiveStatus = "unverified-source-field" }
quests[5465] = { id = 5465, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seelengebundenes Andenken", description = "Kehrt mit dem Andenken zu Marduk zurück, {name}. Er wird Euch über die Anwendung instruieren.", sourceObjective = "Kehrt zu Magistrat Marduk in Darrowehr zurück. Zeigt ihm das seelengebundene Andenken.", sourceObjectiveStatus = "unverified-source-field" }
quests[5466] = { id = 5466, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Lich Ras Frostraunen", description = "Es verbleibt noch eine Aufgabe, {name}. Tretet dem Lich Ras Frostraunen in seinem Unterschlupf gegenüber.\n\nBenutzt die Macht des Andenkens gegen die Bestie - seid unerbittlich in Euren Taten! Haltet den Schlägen stand, mit denen das um sich schlagende Biest Euch sicherlich eindecken wird. Gebt dem Schmerz nicht nach!\n\nWenn das Ritual abgeschlossen ist, wird Ras wieder ein Sterblicher sein. An diesem Punkt muss er getötet werden. Schlagt ihn nieder und nehmt Euch seinen menschlichen Kopf.", sourceObjective = "Sucht Ras Frostraunen in Scholomance. Wenn Ihr ihn gefunden habt, wendet das seelengebundene Andenken auf sein untotes Antlitz an. Solltet Ihr ihn erfolgreich in einen Sterblichen zurückverwandeln können, dann schlagt ihn nieder und nehmt den menschlichen Kopf von Ras Frostraunen an Euch. Bringt den Kopf zu Magistrat Marduk.", sourceObjectiveStatus = "unverified-source-field" }
quests[5481] = { id = 5481, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gordos Aufgabe", description = "Meister will Kräuter. Wir große Hände haben und nicht gut greifen können. Ihr uns helfen und wir Euch nicht wehtun. Wir Düsterkraut brauchen. Viele Kräuter hier und bei Straße.\n\nWenn Ihr Düsterkraut haben, Ihr bringen zu Meister Holland auf den Friedhof von Brill.", sourceObjective = "Sammelt 3 Düsterkräuter und bringt sie zu Jungapotheker Holland auf den Friedhof von Brill.", sourceObjectiveStatus = "unverified-source-field" }
quests[5482] = { id = 5482, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verdammniskraut", description = "Ihr seht also die Zwickmühle, in der ich mich befinde, {name}. Dieses Ding da draußen sammelt die falschen Kräuter! Ich werde Euch dafür belohnen, wenn Ihr sammelt, was ich wirklich benötige. Bringt mir genug Verdammniskraut und ich werde Euch eine angemessene Belohnung geben.\n\nSoweit mir bekannt ist, verseucht es gern die Flora in der Nähe des Massengrabs, nördlich des Friedhofes von Brill. Beeilt Euch und hütet Euch vor den Gnollen in dem Gebiet.", sourceObjective = "Sammelt 10 Verdammniskräuter und bringt sie zu Jungapotheker Holland.", sourceObjectiveStatus = "unverified-source-field" }
quests[5501] = { id = 5501, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Knochenjäger", description = "Wir sitzen hier auf einer Goldmine, das sage ich Euch – einer Goldmine! Kodoknochen werden die Welt für immer verändern... Ich habe Kunden, die daraus Möbel, Musikinstrumente und sogar Sprengpulver herstellen.\n\nEine Karawane kommt hier vorbei, die meine Kodoknochen mitnimmt und sie dann in Schattenflucht verkauft. Wenn Ihr zum Kodofriedhof südlich von hier gehen und mir zehn Kodoknochen bringen könntet, würde ich Euch dafür etwas anderes geben. Ist das ein Geschäft?", sourceObjective = "Bringt Bibbly F'utzbuckel bei Kormeks Hütte 10 Kodoknochen vom Kodofriedhof.", progress = "Habt Ihr die Knochen? Die Karawane wird jeden Moment hier sein. Ich benötige nur noch zehn weitere Kodoknochen, um den Gipfel meiner Karriere zu erreichen. Den Gipfel meiner Karriere, sage ich Euch!", completion = "Ah, prima! Meine Knochen!\n\nIch kann es kaum abwarten, dass die Jungs zuhause mein Gesicht auf dem Titel der Goblinwoche sehen. Ich werde der reichste Goblin auf der Welt sein... und mein Sportlehrer hat immer gesagt, aus mir würde nie was werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[5502] = { id = 5502, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tageseltern der Horde", description = "Ihr wart die ganze Zeit so gut zu mir, {name}. Nie hätte ich erwartet, während der Kinderwoche so viel Spaß zu haben! Danke schön.\n\nIch wünschte, all die anderen Waisenkinder hätten das Glück, die ganzen Sachen zu sehen, die wir gesehen haben. Meint Ihr, wir finden Blax Flaschenzünder wieder und bekommen einen Schaumstoffschwertständer von ihm? Ich glaube, er schiebt noch immer seinen Karren durch die Hauptstraße in der Gasse. Dann könnten alle im Waisenhaus auch ihren Spaß haben!\n\nDanach wird es aber Zeit, nach Hause zurückzukehren.", sourceObjective = "Kauft einen Schaumstoffschwertständer bei Blax Flaschenzünder in Orgrimmars Gasse. Bringt anschließend Euren Schützling in das Waisenhaus von Orgrimmar zurück, indem Ihr die Pfeife des Orcwaisenkindes an Waisenmatrone Schlachterbe in der Gasse übergebt.", progress = "Es ist schön, Euch wiederzusehen, {name}. Habt Ihr die Euch auferlegten Pflichten, für die Ihr Euch während der Kinderwoche freiwillig gemeldet habt, sorgfältig erfüllt?", completion = "Mögen die Geister Euch segnen, {name}. Ihr habt für Grunz mehr getan, als es jemand anderem je in den Sinn käme. Vielen Dank - Ihr seid der Inbegriff eines Helden der Horde.\n\nEuer Geschenk wird den Waisenkindern sehr gefallen. Es kommt schließlich nicht sehr oft vor, dass sie ein neues Spielzeug bekommen.\n\nGrunz hatte so viel Spaß mit Euch, {name}. Er hat mich gebeten Euch eines seiner Lieblingstierchen zu geben, damit Ihr Euch stets an ihn erinnert.", sourceObjectiveStatus = "unverified-source-field" }
quests[5503] = { id = 5503, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anstecknadel der Argentumdämmerung" }
quests[5504] = { id = 5504, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mäntel der Dämmerung", description = "Euer hervorragenden Dienste für die Argentumdämmerung haben sich herumgesprochen, {name}. Wir sind geehrt, Euch in unseren Reihen zu wissen. Ich wurde ermächtigt, Euch einige der wertvollsten Gegenstände der Dämmerung anzubieten - unsere Mäntel des Magiewiderstands.\n\nWenn Ihr einen Mantel mit Eurer Schulterpanzerung verwendet, könnt Ihr Euren Widerstand gegen die Kräfte der Magie auf eine von fünf mögliche Arten verbessern. Als Zeichen der Hingabe für unsere Sache, erbitte ich von Euch nicht weniger als zehn unserer Ehrenmarken, um Zugriff auf die Mäntel zu erhalten.", sourceObjective = "Bringt 10 Ehrenmarken der Argentumdämmerung zu Rüstmeister Hasana ins Bollwerk in den Westlichen Pestländern.", sourceObjectiveStatus = "unverified-source-field" }
quests[5505] = { id = 5505, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schlüssel zur Scholomance" }
quests[5507] = { id = 5507, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mäntel der Dämmerung", description = "Euer hervorragenden Dienste für die Argentumdämmerung haben sich herumgesprochen, {name}. Wir sind geehrt, Euch in unseren Reihen zu wissen. Ich wurde ermächtigt, Euch einige der wertvollsten Gegenstände der Dämmerung anzubieten - unsere Mäntel des Magiewiderstands.\n\nWenn Ihr einen Mantel mit Eurer Schulterpanzerung verwendet, könnt Ihr euren Widerstand gegen die Kräfte der Magie auf eine von fünf mögliche Arten verbessern. Als Zeichen der Hingabe für unsere Sache, erbitte ich von Euch nicht weniger als zehn unserer Ehrenmarken, um Zugriff auf die Mäntel zu erhalten.", sourceObjective = "Bringt 10 Ehrenmarken der Argentumdämmerung zu Rüstmeister Funkellicht im Zugwindlager in den Westlichen Pestländern.", sourceObjectiveStatus = "unverified-source-field" }
quests[5508] = { id = 5508, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geißelsteine des Verderbers" }
